【例 4.7】某商场优惠活动规定，某种商品单价为 80 元，一次购买 5 件以上（包含 5 件）10 件以下（不包含 10 件）打 9 折，一次购买 10 件以上（包含 10 件）打 8 折。设计程序根据不同的购买量计算总价输入购买件数 count，设置单价 price=80 元根据 count 值确定折扣 discount实际售价 amount=pricecountdiscount输出 amount 的值#include <iostream>
using namespace std;
int main() {
    // 输入购买件数
    int count;
    cout << "请输入购买件数：";
    cin >> count;
    // 设置单价
    double price = 80.0;
    double discount;
    // 根据购买件数确定折扣
    if (count >= 10) {
        discount = 0.8;
    } else if (count >= 5) {
        discount = 0.9;
    } else {
        discount = 1.0;
    }

    // 计算实际总价
    double amount = price * count * discount;
    // 输出实际总价
    cout << "实际总价为：" << amount << " 元" << endl;
    return 0;
}
【例 4.8】求一元二次方程 ax^2 + bx + c = 0
 的根，其中系数 aa \neq 0
、b、c 的值由键盘输入输入系数 \(a(a \neq 0)\)、b、c 后，令 \(delta = b^2 - 4ac\)，结果有三种情况若 \(delta = 0\)，方程有两个相同实根；若 \(delta > 0\)，方程有两个不同实根；若 \(delta < 0\)，方程无实根。#include <iostream>
#include <cmath>
using namespace std;
int main（) {
    // 输入系数
    double a, b, c;
    cout << "请输入系数 a（a ≠ 0）：";
    cin >> a;
    cout << "请输入系数 b：";
    cin >> b;
    cout << "请输入系数 c：";
    cin >> c;

    // 计算判别式不能提前计算平方根，因为正负未知
    double delta = b * b - 4 * a * c;

    // 判断根的情况并求解
    if (delta == 0)//不要写成等于
     {
        double x = -b / (2 * a);
        cout << "方程有两个相同的实根：x = " << x << endl;
    } else if (delta > 0) {
        double x1 = (-b + sqrt(delta)) / (2 * a);//注意分子分母的括号
        double x2 = (-b - sqrt(delta)) / (2 * a);
        cout << "方程有两个不同的实根：x1 = "
         << x1 << "，x2 = " << x2 << endl;
    } else {
        cout << "方程无实根" << endl;
    }

    return 0;
}#include<iostream> 
using namespace std; 
void main() {  
 int a=2, b=-1, c=2; 
 if( a<b ) a++; //if已经被逗号给截断了
 c=c+1; 
 cout<< c <<endl ; 
}//c=3#include<iostream> 
using namespace std; 
void main() {  
 int a=2, b=-1, c=2; 
 if( a<b ) ; //if已经被逗号给截断了
 c=c+1; 
