调用标准库函数sin、cos和tan得到三角函数值 
调用三角函数值，实参是弧度，因此要将角度转 
换为弧度。度数doa化为弧度arc： 
• arc=pai*doa/180
#include <iostream>
#include <cmath>
using namespace std;
int main() {
        const float pai = 3.1416; //有名常量pai
        const int inteval = 15; //15度为计算间隔
        //下述8句用于输出标题行(第一行)
        cout.width(10);
        cout << "Angle x";
        cout.width(10);
        cout << "sin(x)";
        cout.width(10);
        cout << "cos(x)";
        cout.width(10);
        cout << "tan(x)";
        float arc; //弧度值arc
        cout.setf(ios::fixed);
        //设置以带小数点的形式输出浮点数
        //cout.flags(ios::fixed);
        //与上一句的功能完全相同
        cout.precision(4); //小数点后保留4位
        for (int doa = 0; doa <= 90; doa += inteval) {
                //度数从0开始, 增量15，直到90
                arc = pai * doa / 180; //化为弧度arc
                cout << endl;
                cout.width(10);
                cout << doa; //输出当前度数doa
                cout.width(10);
                cout << sin(arc);
                cout.width(10);
                cout << cos(arc);
                cout.width(10);
                if (doa == 90) cout << "-"; //90度正切值特殊
                else cout << tan(arc); //非90度时
        }
        cout << endl;
        return 0;
}
