#include<iostream>
#include<cmath>
using namespace std;
int main() {
        cout << "请输入一个整数n"<<endl;
        int n;
        int sum = 0;
        cin >> n;

        for (int j = 2; j < n; j++)
        {
                int isprime = 1;
                //isprime是用来标记当前数 j 是否为质数的，应该在每次判断新的 j 时重新初始化为 1
               // 如果定义在for外面否则，只要有一个数不是质数，isprime会一直保持 0，后续的质数也会被错误判定为非质数。
                for (int i = 2; i <= sqrt(j); i++)
                {
                        if (j % i == 0) { isprime = 0;
