                        for (int b = 1; b <= x ; b++) {
                                a[b][1] = 1;
                                a[b][b] = 1;

                                for (int d = 2; d <= b; d++) {
                                        a[b][d] = a[b - 1][d] + a[b - 1][d - 1];
                                }
                        }
