【例4.35】输入n个学生的注册号和成绩，计算他们的平均成绩，并列出成绩最好的前t名学生的注册号和分数 
Input 6 student's Reg_Num & Score: 
1001 88.5 
1002 91 
1003 85.5 
1004 93.5 
1005 85 
1006 96 
Average score:89.9 
register-number score 
1 1006 96.0 
2 1004 93.5 
3 1002 91.0
#include <iostream>
using namespace std;
int main() {
        const int n = 6;          //共有n个学生
        const int t = 3;          //欲找出前t名最好成绩者
        struct student {
                int index;
                float score;
        }scoretab[n];//定义一个以结构为元素的数组，其中的结构名称分别是scoretab[i]
        float sum = 0;
        for (int i = 0; i < n; i++) {//输入注册号及成绩
                cin >> scoretab[i].index >> scoretab[i].score;
                sum += scoretab[i].score;
        }
        cout.setf(ios::fixed);//设置以定点数格式输出
        cout.precision(1); //点后保留1位
        //输出平均成绩 
        cout << endl << "Average score:" << sum / n << endl;
        cout.width(25);
        //输出“题头行”
        cout << "register-number score" << endl;

        for (int i = 0; i < t; i++) {        //找出前t名最好者
                //从i分量始 score中的最大者s
                float s = scoretab[i].score;
                int j1 = i; //j1中记录上述最大者的下标i
                //看还有否比s 更大的
                for (int j = i + 1; j < n; j++) {
                        if (s < scoretab[j].score) {//有更大的时
                                s = scoretab[j].score; //更大者放s
                                j1 = j;         //对应下标放j1
                        }
                }//for j 循环体结束
                if (j1 > i) {
                        //若scoretab[i].score到scoretab[n-1].score        //中的最大者并非score[i]时，要进行交换
                        student temp = scoretab[j1];
                        scoretab[j1] = scoretab[i];
                        scoretab[i] = temp;
                }
                cout.width(4);
                //输出名次号（前t名的第i+1名）        cout<<endl<<i+1; 
                cout.width(11);
                //输出第i名学生的注册号
                cout << scoretab[i].index;
                cout.width(12);
                cout.precision(1);          //点后保留1位
                //输出第i名学生的成绩
                cout << scoretab[i].score << endl;
        }                                   //for i 循环体结束
        cout << endl;
        return 0;
}                                         //main结束

