算法
枢值归位
枢值是指在排序序列中指定的某个值，一般是排序序列的中间元素的值
在排序过程中，可以多次指定枢值，并放到排序序列（或者子序列）的末尾位置（亦可以放在首位置）
二分有序
将元素序列以枢值为界，分为左右两个部分，左边的值都小于枢值，而右边的值都大于枢值
快速排序
#include <iostream>
#include <vector>
using namespace std;

int partition(vector<int>& arr, int left, int right) {
    // 1. 选最右侧元素作为枢值（pivot），这是快速排序的常见选择
    int pivot = arr[right]; 
    // 2. i是“左区的右边界指针”，初始在左边界left的左边（-1位置），表示左区一开始为空
    int i = left - 1;       

    // 3. 遍历从left到right-1的所有元素（因为right是枢值，不用遍历）
    for (int j = left; j < right; j++) {
        // 4. 如果当前元素≤枢值，说明它应该划入左区
        if (arr[j] <= pivot) {
            i++; // 左区边界右移一位，给当前元素腾位置
            swap(arr[i], arr[j]); // 把当前元素放到左区的新位置
        }
        // 5. 如果当前元素>枢值，不做任何操作，j继续右移（自然划入右区）
    }
    // 6. 遍历结束后，i+1就是枢值的正确位置（左区最后一个元素的下一位）
    swap(arr[i + 1], arr[right]);
    // 7. 返回枢值索引，供快速排序递归使用
    return i + 1; 
}

// 快速排序递归函数
//也就是这个函数通过不断取枢值的方式来排序
void quickSort(vector<int>& arr, int left, int right) {
    // 递归终止条件：子数组长度≤1（left >= right）
    if (left >= right) {
        return;
    }
    // 1. 枢值归位，得到枢值索引
    int pivotIndex = partition(arr, left, right);
    // 2. 递归处理左子数组（[left, pivotIndex-1]）
    quickSort(arr, left, pivotIndex - 1);
    // 3. 递归处理右子数组（[pivotIndex+1, right]）
    quickSort(arr, pivotIndex + 1, right);
}

// 测试函数
int main() {
    vector<int> arr = {5,2,9,3,7,6,1,8,4};
    cout << "排序前：";
    for (int num : arr) {
        cout << num << " ";
    }
    cout << endl;

    quickSort(arr, 0, arr.size() - 1); // 调用快速排序

    cout << "排序后：";
    for (int num : arr) {
        cout << num << " ";
    }
    cout << endl;
    return 0;
}
