引用成员变量
C++ 的引用（&）必须在定义时绑定一个对象，不能先创建空引用，再后期绑定 —— 函数体里的赋值本质是给引用绑定的对象改值，而非绑定引用，直接编译报错。
class Test {
private:
    int& ref; // 引用成员
public:
    // 正确：初始化列表定义时绑定外部变量
    Test(int& r) : ref(r) {}
    // 错误：引用未定义就使用，无法后期绑定
    // Test(int& r) { ref = r; } 
};
复制过程都在函数体前面完成了，这函数体有啥用？
初始化列表只是 “初始化成员”，但构造函数的函数体可以做这些事：
执行额外的业务逻辑:如打印对象创建信息初始化动态资源
class Array {
private:
    int* arr;  // 动态数组
    int size;
public:
    Array(int s) : size(s) {  // 初始化列表处理size
        // 函数体：分配堆内存（动态资源）
        arr = new int[size];
        // 函数体：初始化数组元素
        for (int i=0; i<size; i++) {
            arr[i] = 0;
        }
    }
};
处理复杂的初始化逻辑初始化列表只能做 “简单的成员赋值”，如果需要条件判断、循环等复杂逻辑，必须放在函数体中：
Student(string n, int a) : name(n) {
    // 函数体：根据条件调整age
    if (a < 0) {
        age = 0;
        cout << "年龄不合法，已设为0" << endl;
    }
    else {
        age = a;
    }
}
构造函数实例：
#include <iostream>
#include <string>
using namespace std;
class Person {
private:
    string name;
    int age;
    string gender;

public:
    // 重载1：无参构造（默认构造）——创建“默认对象”
    Person() {
        name = "未知";
        age = 0;
        gender = "未知";
        cout << "无参构造：创建默认Person对象" << endl;
    }

    // 重载2：单参构造——只指定姓名，年龄/性别用默认值
    Person(string n) {
        name = n;
        age = 0;
        gender = "未知";
        cout << "单参构造：创建姓名为" << n << "的Person对象" << endl;
    }

    // 重载3：三参构造——指定所有属性，精准创建对象
    Person(string n, int a, string g) {
        name = n;
        age = a;
        gender = g;
        cout << "三参构造：创建完整属性的Person对象" << endl;
    }

    void showInfo() const {
        cout << "姓名：" << name << "，年龄：" << age << "，性别：" << gender << endl;
    }
};

int main() {
    // 不同参数列表，调用不同的构造函数（重载生效）
    Person p1; // 调用无参构造
    Person p2("张三"); // 调用单参构造
    Person p3("李四", 25, "男"); // 调用三参构造

    p1.showInfo(); // 姓名：未知，年龄：0，性别：未知
    p2.showInfo(); // 姓名：张三，年龄：0，性别：未知
    p3.showInfo(); // 姓名：李四，年龄：25，性别：男
    return 0;
}
拷贝构造函数
基本数据类型：数字（int/float）、字符串（string）、布尔值（bool）、null/undefined 等
特点：值直接存在栈内存中，拷贝时直接复制「具体的值」，不存在深浅之分。
引用数据类型：对象（Object）、数组（Array）、函数（Function）等
特点：实际数据存在堆内存，栈内存中只存一个「地址指针」，指向堆内存的真实数据。
关键：拷贝引用类型时，浅拷贝复制的是地址，深拷贝复制的是堆内存里的真实数据。
拷贝构造函数的唯一作用就是「创建新对象」，而「把一个已创建的对象复制给另一个已创建的对象」是赋值运算符重载的工作，不是拷贝构造函数。
#include<iostream>
using namespace std;

//1.构造函数的分类及调用
//分类：按照参数分为：无参构造函数 和 有参构造函数
          //按照类型分为：普通构造函数 和 拷贝构造函数
class person
{
public:

        int age;
        person()
        {
                cout << "person的无参（默认）构造函数被调用了！" << endl;
        }
        person(int a)
        {
            age = a;
                cout << "person的有参构造函数被调用了！" << endl;
        }
        //拷贝构造函数
        person(const person &p)//限定本体不能改动
        {
                cout << "person的拷贝构造函数被调用了！" << endl;
                age = p.age;//将传入的人身上所有属性拷贝过来
        }

        ~person()
        {
                cout << "person的析构函数被调用了！" << endl;
        }

};   

//调用
void test01()
{
        //1.括号法
        person p;//默认（无参）构造函数的调用. 不要加括号，否则会被当成函数声明,不会认为在创建对象
        person p2(10);//有参构造函数的调用
        person p3(p2);//拷贝构造函数的调用
        cout << p2.age << endl;
        cout << p3.age << endl;

        //2.显示法
        person p4;
        person p5 = person(10);//有参构造函数
        person p6 = person(p2);//拷贝构造函数
        //person(10)匿名对象，执行完这行代码后就会被销毁. 放到等号右面就有名了

           //不要利用拷贝构造函数，初始化匿名对象  编译器会认为person(p6)等价于person p6,对象声明

        //3.隐式转换法
        person p7 = 10;//相当于写了person p7 = person(10);有参构造函数
        person p8 = p7;//拷贝构造

}
int main()
{
        test01();

}
