返回对象（值）：拷贝构造函数会被调用，创建一个新的副本返回，原对象不变（但函数内部可能已修改原对象）。
person personaddage(person & p)  // 返回 person，而不是 person&
{
    this->age += p.age;
    return *this;   // 这里会发生什么？
}
返回引用：不调用拷贝构造函数，直接返回原对象。
person& personaddage(person & p)  // 返回引用
{
    this->age += p.age;
    return *this;   // 返回的是原对象的引用
}
浅拷贝
浅拷贝只会复制栈内存中的内容：
对基本类型：直接复制值（和普通赋值没区别）；对引用类型：只复制堆内存的地址指针，不会复制堆里的真实数据。
影响：
数据互相篡改：多个对象的指针指向同一块堆内存，修改一个对象的堆数据，其他对象也会受影响；双重释放（double free）：对象析构时，都会调用delete释放同一块堆内存，直接触发程序崩溃。
深拷贝
深拷贝会逐层遍历原数据，对每一层的数据都做完整复制：
对基本类型：直接复制值；对引用类型：重新在堆内存开辟一块新空间，复制原堆里的真实数据，栈内存新的地址指针
比如person有成员变量int*p=new int (5);
 person(const personTom) {p=new int(*Tom)}
class person
{
public:
        person(int a,int h)
        {
                age = a;
                height = new int(h);
                cout << "有参构造函数的调用" << endl;
        }
       // 格式：
        person(const person& p)
        {       
                if(p.height!=nullptr){//防止解引用空指针
                //height=p.height;//编译器默认实现
                    height = new int(*(p.height)); //防止解引用空指针  
                }
                else{height=nullptr;}
                age = p.age;              
                cout << "拷贝构造函数的调用" << endl;
        }
        ~person()
        {
                if (height != NULL)
                {
                        delete height;
                        height = NULL;
                }
                cout << "析构函数的调用" << endl;
        }
        int  GetAge()
        {
                return age;
        }
        int GetHeight()
        {
                return *height;
        }
private:
        int age;
        int *height;
};
int main()
{
        person p1(18, 160);
        cout << "p1的年龄为：" << p1.GetAge() << " p1的身高为：" << p1.GetHeight() << endl;
        person p2(p1);
        cout << "p2的年龄为：" << p2.GetAge() << " p2的身高为：" << p2.GetHeight() << endl;
        return 0;
}

