{
        cout << "person拷贝构造函数" << endl;
        Age = p.Age;
        //Height =p.Height;编译器默认实现这行代码
        //深拷贝操作:重新创建内存
        Height = new int(*p.Height);
}    自己提供拷贝构造

总结：
函数名和类名完全相同（和普通构造函数一样）；
唯一的参数是「当前类的 const 引用」（格式：类名(const 类名& 形参名)）。
拷贝构造函数属于类的成员函数，遵循 “类内声明、类外定义”（简单类可直接类内定义），只读不修改源对象，所以参数必须加 const，且必须传引用
加「const」：保护源对象，防止被意外修改传「引用」：避免无限递归调用拷贝构造函数
传值时编译器会自动创建实参的临时拷贝，而创建这个临时拷贝又会调用拷贝构造函数，最终导致无限递归，编译器直接报错。
<类名> <对象名2>(<对象名1>); 
<类名> <对象名2> = <对象名1>;
C++ 中拷贝构造函数调用时机通常有三种情况
场景 1：直接用一个对象初始化另一个新对象场景 2：函数的形参是类的值传递场景 3：函数返回值是类的值传递
C++标准支持带有一个参数的构造函数，将参数类型隐式转换为相应的类类型。
class A
{
public:
    A(int x) { num = x; } // 单参构造
    int num;
};

int main()
{
    A a = 100; // ✅ 合法！隐式转换
    // 编译器自动：100 → 调用A(int)构造 → 生成临时对象赋值
    return 0;
}
加 explicit 禁止隐式转换
class A
{
public:
    explicit A(int x) { num = x; }
    int num;
};

int main()
{
    A a = 100;   // ❌ 编译报错，禁止隐式转换
    A b(100);    // ✅ 合法，显式调用构造
    A c = A(200);// ✅ 合法，手动显式构造
    return 0;
}
