析构函数
#include <iostream>
using namespace std;
// 1、构造函数分类
// 按照参数分类分为 有参和无参构造   无参又称为默认构造函数
// 按照类型分类分为 普通构造和拷贝构造
class Person {
public:
    // 无参（默认）构造函数
    Person() {
        cout << "无参构造函数!" << endl;
    }

    // 有参构造函数
    Person(int a) {
        age = a;
        cout << "有参构造函数!" << endl;
    }

    // 拷贝构造函数
    Person(const Person& p) {
        age = p.age;
        cout << "拷贝构造函数!" << endl;
    }

    // 析构函数
    ~Person() {
        cout << "析构函数!" << endl;
    }

public:
    int age;
};

// 2、构造函数的调用
// 调用无参构造函数
void test01() {
    Person p; // 调用无参构造函数
}

// 调用有参的构造函数
void test02() {
    // 2.1 括号法，常用
    Person p1(10);
    // 注意1：调用无参构造函数不能加括号，如果加了编译器认为这是一个函数声明
    // Person p2();

    // 2.2 显式法
    Person p2 = Person(10);
    Person p3 = Person(p2);
    // Person(10)单独写就是匿名对象 当前行结束之后，马上析构

    // 2.3 隐式转换法
    Person p4 = 10; // 等价于 Person p4 = Person(10);
    Person p5 = p4; // 等价于 Person p5 = Person(p4);

    // 注意2：不能利用 拷贝构造函数 初始化匿名对象 编译器认为是对象声明
    // Person p5(p4);
}

int main() {
    test01();
    // test02();
    return 0;
}
#include <cstring>
class Student {
private:
    char* _name; // new[] 开辟（字符串）
    int* _score; // new 开辟（单个int）
    int* _arr;   // new[] 开辟（int数组）
public:
    Student(const char* name, int score, int arr[], int n) {
        // 构造：依次初始化指针（new[]、new、new[]）
        _name = new char[strlen(name)+1];
        strcpy(_name, name);
        _score = new int(score);
        _arr = new int[n];
        for (int i=0; i<n; i++) _arr[i] = arr[i];
    }

    // 析构：逐个释放，匹配开辟方式
    ~Student() {
        // 释放new[]的_name
        if (_name) { delete[] _name; _name = nullptr; }
        // 释放new的_score
        if (_score) { delete _score; _score = nullptr; }
        // 释放new[]的_arr
        if (_arr) { delete[] _arr; _arr = nullptr; }
    }

    // 深拷贝（必写，每个指针都要单独深拷贝）
    Student(const Student& s) {
        _name = new char[strlen(s._name)+1];
        strcpy(_name, s._name);
        _score = new int(*s._score);
        // 数组拷贝需先知道长度，这里假设存了长度成员_len，省略
        _arr = new int[s._len];
        for (int i=0; i<s._len; i++) _arr[i] = s._arr[i];
    }
    // 赋值运算符重载同理，先释放所有指针，再逐个深拷贝
};
