嵌套类
嵌套类只是「类型上的嵌套定义」，并不是「对象上的包含关系」，每一个嵌套类的对象，并不会天然绑定 / 包含一个外部类的对象，两者的对象是完全独立的。
创建格式：
大类::被嵌套的类 类名；
运算符的重载
如下5个运算符不可重载：
  .    ::    ?:    .*    sizeof
只能以类成员而不能以友元身份重载的运算符:
  =    ( )    [ ]   ->   typedef
我的习惯：加减乘除左移右移友元函数，其余统统类成员
不能改变运算符的优先级和操作数个数（+是双目运算符，必须两个操作数）；不能重载 C++ 的内置运算符含义（比如不能让int + int变成减法）；重载建议返回新对象，而不是修改原对象（符合a = b + c的常规逻辑，b 和 c 本身不变）
加号+加减乘除
成员函数
全局函数（友元）
#include <iostream>
using namespace std;
// 自定义测试类：二维坐标类
class Point {
private:
    int x;  // x坐标
    int y;  // y坐标
public:
    // 构造函数：初始化x、y，带默认参数
    Point(int x_ = 0, int y_ = 0) : x(x_), y(y_) {}
    // 1. 成员函数重载+：对象 + 对象
    Point operator+(const Point& other) {
        Point temp;
        temp.x= this->x + other.x;
        temp.y=this->y + other.y;
        return temp;
    }
    // 2. 成员函数重载+：对象 + 数值
    Point operator+(int num) {
        Point temp;
        temp.x = this->x + num;
        temp.y = this->y + num;
        return temp;
    }
    //但是无法写数值+对象
    // 3. 友元声明：所有+重载函数（访问私有成员）
    friend Point operator+(const Point& p1, const Point& p2);  // 对象+对象
    friend Point operator+(const Point& p, int num);           // 对象+数值
    friend Point operator+(int num, const Point& p);           // 数值+对象

    // 辅助函数：打印坐标，查看结果
    void print(const string& name) const {
        cout << name << " = (" << x << ", " << y << ")" << endl;
    }
};
//不能返回类的引用，因为返回的是函数内部创建的临时对象 temp，它出了函数就会被销毁！
// 4. 全局友元重载+：对象 + 对象
Point operator+(const Point& p1, const Point& p2) {
    Point temp = p1;
    temp.x = p1.x + p2.x;
    temp.y = p1.y + p2.y;
    return temp;
}

// 5. 全局友元重载+：对象 + 数值
Point operator+(const Point& p, int num) {
    Point temp = p;
    temp.x += num;
    temp.y += num;
    return temp;
}

// 6. 全局友元重载+：数值 + 对象（复用对象+数值，实现交换律）
Point operator+(int num, const Point& p) {
    return p + num;  // 直接复用，避免重复代码
}

// 主函数测试所有场景
int main() {
    Point p1(1, 2), p2(3, 4);
    // 测试1：对象 + 对象
    Point p3 = p1 + p2;
    p3.print("p1 + p2");  // 输出(4, 6)
    // 测试2：对象 + 数值
    Point p4 = p1 + 5;
    p4.print("p1 + 5");   // 输出(6, 7)
    // 测试3：数值 + 对象（交换律）
    Point p5 = 5 + p1;
    p5.print("5 + p1");   // 输出(6, 7)

    return 0;
}
