        //构造函数定长度
        ma(int n,int m) : n(n), m(m) {
                data = new int* [n];
                for (int i = 0; i < n; i++) {
                        data[i] = new int[m];
                }
        }
        //友元重载
        friend istream& operator>>(istream& cin, ma& ma);
