3.递增++
#include<iostream>
using namespace std;
//重载递增运算符

class MyInteger {

        friend ostream& operator<<(ostream& cout, MyInteger myint);

private:
        int m_num;
public:
        MyInteger()
        {
                m_num = 0;
        }

        //重载前置++
        MyInteger &operator++()  //返回引用为了一直对一个数据进行递增操作
        {
                m_num++;//先进行++运算
                return *this;//再返回对象本身
        }

        //重载后置++
        MyInteger operator++(int) //int代表占位参数，用于区分前置和后置递增
        {
                //先记录当时结果
                MyInteger temp = *this;
                //后递增
                m_num++;
                //最后返回记录结果
                return temp;
        }//后置递增返回值为对象本身，不能返回引用，因为返回的是一个临时对象，函数结束后会被销毁。

};

//重载左移
ostream &operator<<(ostream& cout, MyInteger myint) //拷贝，避免&导致返回的临时对象被销毁而引发错误
{
        cout << myint.m_num;
        return cout;
}


void test01()
{
        MyInteger myint;
        cout <<++(++myint) << endl;
        cout << myint << endl;
}

void test02()
{
        MyInteger myint;
        cout << myint++ << endl;
        cout << myint << endl;        
}


int main()
{
        test01();
        test02();
}


后置++（如 obj++）对应的重载函数必须有一个额外的 int 参数，这个 int 纯粹用于区分签名，不需要传递实际值，通常也不使用。
如果运算符在操作数前面（前置），就匹配无参版本。如果运算符在操作数后面（后置），就匹配带 int 参数的那个版本。

前置 ++ 返回左值（对象本身），可以用引用接收。后置 ++ 返回右值（临时对象），不能用引用接收，只能用值传递或const 引用（推荐 const 引用）接收。
#include <iostream>
using namespace std;

class Num {
private:
    int val;
public:
    // 构造函数
    Num(int v = 0) : val(v) {}

    // 打印值
    void show() const {
        cout << val << endl;
    }

    // 1. 前置 ++ 重载
    Num& operator++() {
        val++;        // 先自增
        return *this; // 返回自身引用
    }

    // 2. 后置 ++ 重载，int只是占位区分，不用传参
    Num operator++(int) {
        Num temp = *this; // 保存原来的值
        val++;            // 对象自身自增
        return temp;      // 返回旧值副本
    }
};

int main() {
    Num a(10);
    cout << "前置++：";
    ++a;
    a.show(); // 11

    Num b(20);
    cout << "后置++输出原值：";
    (b++).show(); // 打印20（返回的是自增前的临时对象）
    cout << "后置++后对象本身：";
    b.show();     // 21

    return 0;
}

