#89分数类

cin 读取数据时，默认会以「空白符（空格 / 回车 / 制表符）」作为分隔符，但对于 12/24 这种无空白符的字符串，我们可以主动指定分隔字符（/），让 cin 按「分子→/→分母」的顺序读取，步骤如下：
cin 读取整数（分子）：遇到非数字字符（/）时停止，把前面的数字（12）存入分子变量；cin 读取字符（/）：跳过 / 忽略这个分隔符，只需要把它存到一个临时字符变量里即可；cin 读取整数（分母）：从/后面继续读取数字（24），存入分母变量。
#include<iostream>
using namespace std;
//辗转相除法求最大公约数
int gongyueshu(int a, int b) {
        if (a % b == 0) {
                return b;
        }
        return gongyueshu(b, a % b);
}
//求最大公倍数
int gongbeishu(int a, int b) {
        return (a * b) / gongyueshu(a, b);
}
class fraction {
private:
        int m_up;//分子
        int m_down;//分母
public:
        fraction& set();//输入
        void tongfenprint();//通分输出
        void print();//输出
        void yuefen();//约分
        friend  void tongfen(fraction& a, fraction& b);//通分
        fraction upside();//倒数
        friend void compare( fraction& a, fraction&b);//比较
        friend fraction operator+(const fraction a, const fraction b);
        friend fraction operator-(const fraction a, const fraction b);
        friend fraction operator*(const fraction a, const fraction b);
        friend fraction operator/(const fraction a, const fraction b);
        fraction& operator=(const fraction& a);

};
//输入
fraction& fraction::set() {
        int up, down;
        char p;
        cin >> up >> p >> down;
        if (down == 0) {
                cout << "分母不能为零！" << endl;
                exit(1);
        }
        m_up = up;
        m_down = down;
        return *this;
}
//通分输出
void fraction::tongfenprint() {
        if (m_down == 1) {
                cout << m_up << endl;
        }
        cout << m_up << '/' << m_down << endl;
}
//输出
void fraction::print() {
        (*this).yuefen();
        if (m_down == 1) {
                cout << m_up << endl;
        }
        else {
                cout << m_up << '/' << m_down << endl;
        }        
}
//约分
void fraction::yuefen() {
        int tem = gongyueshu(m_up, m_down);
        m_up /= tem;
        m_down /= tem;
        return;
}
//通分
void tongfen(fraction& a, fraction& b) {
        int tem = gongbeishu(a.m_down, b.m_down);
        a.m_up = a.m_up * (tem / a.m_down);
        b.m_up = b.m_up * (tem / b.m_down);
        a.m_down = tem;
        b.m_down = tem;
}
//倒数
fraction fraction::upside() {
        fraction tem;
        tem.m_up = m_down;
        tem.m_down = m_up;
        return  tem;
}
void compare( fraction& a,  fraction& b) {
        tongfen(a, b);
        if (a.m_up > b.m_up) {
                cout << '>' << endl;
        }
        else if (a.m_up == b.m_up) {
                cout << '=' << endl;
        }
        else { cout << '<' << endl; }

}
fraction& fraction::operator= (const fraction& a) {
        m_up = a.m_up;
        m_down = a.m_down;
        return *this;
}
fraction operator+(const fraction a, const fraction b) {
        fraction tem;
        fraction tem_a = a;
        fraction tem_b = b;
        tongfen(tem_a, tem_b);
        tem.m_up = tem_a.m_up + tem_b.m_up;
        tem.m_down = tem_a.m_down;
        return tem;
}
fraction operator-(const fraction a, const fraction b) {
        fraction tem;
        fraction tem_a = a;
        fraction tem_b = b;
        tongfen(tem_a, tem_b);
        tem.m_up = tem_a.m_up - tem_b.m_up;
        tem.m_down = tem_a.m_down;
        return tem;
}
fraction operator*(const fraction a, const fraction b) {
        fraction tem;
        tem.m_up = a.m_up * b.m_up;
        tem.m_down = a.m_down * b.m_down;
        return tem;
}
fraction operator/(const fraction a, const fraction b) {
        fraction tem;
        tem.m_up = a.m_up *b.m_down;
        tem.m_down = a.m_down*b.m_up;
        return tem;
}


int main() {
        int n;
        fraction a, b;
        cin >> n;
        a.set();
        b.set();
        for (int i = 0; i < n; i++) {
                int rule;
                cin >> rule;
                switch (rule) {
                case 1:
                        fraction t1 = a + b;
                        t1.print();
                        break;
                case 2:
                        fraction t2 = a - b;
                        t2.print();
                        break;
                case 3:
                        fraction t3 = a * b;
                        t3.print();
                        break;
                case 4:
                        fraction t4 = a / b;
                        t4.print();
                        break;
                case 5:
                        tongfen(a, b);
                        a.tongfenprint();
                        b.tongfenprint();
                        break;
                case 6:
                        compare(a, b);
                        break;
                case 7:
                        a.yuefen();
                        a.print();
                        break;
                case 8:
                        fraction tem;
                        tem = a.upside();
                        tem.print();
                        break;
                }
        }
        return 0;
}

链表
定义
链表：一种动态线性数据结构，由一个个节点通过指针依次连接而成。
每个节点 = 数据域 + 指针域
数据域：存数据
指针域：存下一个节点地址
结构特点
内存不连续，分散存放
没有固定大小，动态开辟内存
意义
解决数组三大痛点：数组长度固定，容易溢出 / 浪费空间。数组插入、删除元素大量移动元素，效率极低。数组必须开辟连续大块内存
注:下面这个覆盖了链表所有可能的考点，,是精华所在，只要搞会了，所有基础链表题就都会做了
这个后面是于同学的总结，循序渐进，这个看不懂可以看下面，看懂了可以直接跳过
#include<iostream>
#include<algorithm>
using namespace std;
struct node {
        int val;
        node* next;
        node(int val):val(val),next(NULL){}
};
class list{
public:
        node* head;
        node* tail;
        int count;
        list():count(0),head(NULL),tail(NULL){}
        // 一、尾插法：在尾部添加节点
        void pushback(int val) {
                node* newnode = new node(val);
                if (tail == NULL) {
                        head = newnode;
                        tail = newnode;
                        count++;
                        return;
                }
                tail->next = newnode;
                tail = newnode;
                count++;
        }
        // 二、头插法：在头部添加节点
        void pushforward(int val) {
                node* newnode = new node(val);
                if (head == NULL) {
                        head = newnode;
                        tail = newnode;
                        count++;
                        return;
                }
                newnode->next = head;
                head = newnode;
                count++;
        }
        // 三、 在第 k 个位置插入 val（位置从 1 开始）
        void insert(int k, int val) {
                node* newnode = new node(val);
                if (k<1 || k>count+1) {
                        cout << "插入失败" << endl;
                        return;
                }
                if (k == 1) {
                        newnode->next = head;
                        head = newnode;
                        if (tail == NULL) {
                                tail = newnode;
                        }
                        count++;
                        return;
                }
                node* curr = head;
                for (int i = 1; i < k - 1; i++) {
                        curr = curr->next;
                }
                newnode->next = curr->next;
                curr->next = newnode;
                if (newnode->next == NULL) {
                        tail = newnode;
                }
                count++;
        }
        //四、删除第k个位置的节点
        void Delete(int k) {
                if (k<1 || k>count) {
                        cout << "删除失败" << endl;
                        return;
            }
                //头节点
                node* curr = head;
                if (k == 1) {
                        head = head->next;
                        delete curr;
                        curr = NULL;
                        count--;
                        return;
                }
                for (int i = 1; i < k - 1; i++) {
                        curr = curr->next;
                }
                node* tem = curr->next; 
                //如果是尾节点
                if (curr->next->next == NULL) {
                        tail = curr;
                        delete tem;
                        tem = NULL;
                        count--;
                        return;
                }
                curr->next = curr->next->next;
                delete tem;
                tem = NULL;
                count--;
        }
        //五、遍历打印链表 
        void print() {
                node* curr = head;
                while (curr != NULL) {
                        cout << curr->val<<' ';
                        curr = curr->next;
                }
        }
        //六、获取链表长度
        int getlength() {
                return count;
        }
        //遍历型
        int getlen() {
                node* curr = head;
                int cou=0;
                while (curr != NULL) {
                        curr->next;
                        cou++;
                }
                return cou;
        }
        //七、按值查找节点位置
        int find(int k) {
                node* curr = head;
                int index=0;
                while (curr != NULL) {
                        index++;
                        if (curr->val == k) {
                                return index;
                        }
                        curr = curr->next;
                }
                        return -1;
        }
        //八、反转链表
        void reverseList() {
                node* pre = nullptr;
                node* curr = head;
                node* next = nullptr;
                while (curr != nullptr) {
                        next = curr->next;  // 1. 先存好原来的下一个节点，防止断链找不到后面
                        curr->next = pre;   // 2. 反转当前节点的指向，不再往后，改为指向前一个
                        pre = curr;         // 3. pre往前挪一步，变成当前节点
                        curr = next;        // 4. curr往后走，处理下一个节点
                }
                // 翻转后原尾节点变成头，原头节点变成尾
                tail = head;
                head = pre;
        }
        //九、判断是否有环
        bool hascycle() {
                node* fast = head;
                node* slow = head;
                while (fast!=NULL&&fast->next!=NULL) {
                        fast = fast->next->next;
                        slow = slow->next;
                        if (slow == fast) { return true; }
                }
                return false;
        }
        //十、 返回中间节点的指针
        node* getMid() {
                if (head == nullptr)
                        return nullptr;
                node* slow = head;
                node* fast = head;
                // 循环条件：fast和fast->next不为空就继续走
                while (fast != nullptr && fast->next != nullptr) {
                        slow = slow->next;
                        fast = fast->next->next;
                }
                return slow;
        }
        //十一、删除重复数据
        void delRepeat() {
                if (head == nullptr) return;
                node* curr = head;
                while (curr->next != nullptr) {
                        // 后一个节点和当前值重复，删除后一个
                        if (curr->val == curr->next->val) {
                                node* temp = curr->next;
                                curr->next = curr->next->next;
                                delete temp;
                                count--;
                        }
                        else {
                                // 不重复才后移
                                curr = curr->next;
                        }
                }
                tail = curr; // 最后更新尾指针
        }

};


创建链表
头插法和尾插法
class LinkedList {
private:
    Node* head;  // 头指针
public:
    // 构造函数：初始化空链表
    LinkedList() : head(nullptr) {}
    // 尾插法：在尾部添加节点
    void append(int value) {
        Node* newNode = new Node(value); // 在堆上创建新节点
        //newNode只是一个临时指针，函数结束后销毁
        if (head == nullptr) {
            // 空链表，直接让 head 指向新节点
            head = newNode;
        } else {
            // 找到最后一个节点
            Node* current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            // 将最后一个节点的 next 指向新节点
            current->next = newNode;
        }
    }

    // 头插法：在头部添加节点
    void prepend(int value) {
        Node* newNode = new Node(value);
        newNode->next = head; // 新节点的 next 指向当前头节点
        head = newNode;       // 头指针指向新节点
    }
};
