示例同ppt
#include <iostream>
using namespace std;

// 节点定义
struct Node
{
    int num;
    Node* next;
    // 构造函数
    Node(int n) : num(n), next(NULL) {}
};

// 链表类
class List
{
private:
    Node* head;       // 头指针
    Node* tail;       // 尾指针（PPT里用了尾指针优化头尾插）
    int nodeCount;    // 节点计数器
public:
    List() : head(NULL), tail(NULL), nodeCount(0) {}
    ~List()
    {
        // 析构释放内存（可选补充）
        Node* p = head;
        while(p != NULL)
        {
            Node* del = p;
            p = p->next;
            delete del;
        }
    }
    // PPT核心插入函数：有序从小到大插入
    void Insert(int n);
    // 辅助打印函数，测试用
    void Show();
};

// PPT原版Insert函数，一字不差逻辑
void List::Insert(int n)
{
    Node* tmp = new Node(n);
    // 情况1：空链表
    if (head == NULL)
    {
        head = tail = tmp;
        nodeCount++;
    }
    else
    {
        // 情况2：头插，新值比头结点小
        if (n < head->num)
        {
            tmp->next = head;
            head = tmp;
            nodeCount++;
            return; // 头插完成直接退出函数
        }
        // 情况3：尾插，新值比尾结点大
        if (n > tail->num)
        {
            tail->next = tmp;
            tail = tmp;
            nodeCount++;
            return; // 尾插完成直接退出函数
        }
        // 情况4：中间查找插入
        Node* curr = head;
        while (curr->next != NULL)
        {
            if ((curr->num <= n) && (curr->next->num > n))
            {
                tmp->next = curr->next;
                curr->next = tmp;
                nodeCount++;
                return;
            }
            curr = curr->next;
        }
    }
}

// 遍历打印链表（测试用）
void List::Show()
{
    Node* p = head;
    while(p != NULL)
    {
        cout << p->num << " ";
        p = p->next;
    }
    cout << endl;
}

