{
    List lst;
    lst.Insert(10);
    lst.Insert(5);   // 头插
    lst.Insert(20);  // 尾插
    lst.Insert(15);  // 中间插入 10和20之间
    lst.Show();      // 输出：5 10 15 20
    return 0;
