删除节点
要删除某个节点，必须知道它的前驱节点，让前驱的 next 跳过被删节点，再释放内存。
只删第一个出现的重复节点
bool remove(int value) {
    if (head == nullptr) return false; // 空链表
    // 如果删除的是头节点
    if (head->data == value) {
        Node* temp = head;
        head = head->next;   // 头指针后移
        delete temp;         // 释放旧头节点的内存
        return true;
    }

    // 查找前驱节点
    Node* current = head;
    while (current->next != nullptr && current->next->data != value) {
        current = current->next;
    }
    if (current->next == nullptr) {
        return false; // 没找到
    }
    // 删除 current->next
    Node* temp = current->next;
    current->next = temp->next;  // 跳过 temp
    delete temp;                 // 释放内存
    return true;
}
删掉全部重复节点
void removeAll(int value) {
    if (head == nullptr) return;    // 空链表直接返回

    // 第一步：循环删除所有开头是 value 的节点
    while (head != nullptr && head->data == value) {
        Node* temp = head;
        head = head->next;
        delete temp;
    }

    // 第二步：循环删除中间和末尾所有是 value 的节点
    Node* current = head;
    while (current != nullptr && current->next != nullptr) {
        if (current->next->data == value) {
            // 找到就删掉
            Node* temp = current->next;
            current->next = current->next->next;
            delete temp;
        } else {
            // 没找到才往后走
            current = current->next;
        }
    }
}
