//继承中同名处理

class Base {
public:
        int m_a;
        Base()
        {
                m_a = 100;
        }

        void func()
        {
                cout << "Base func" << endl;
        }

        void func(int a)
        {
                cout << "Base func(int a)" << endl;
        }
};

class Son :public Base {
public:
        int m_a;
        Son()
        {
                m_a = 200;
        }
        void func()
        {
                cout << "Son func" << endl;
        }
};


void test01()  //同名成员属性
{
        Son s;
        cout << "Son "<<s.m_a << endl;
        cout << "Base " <<s. Base::m_a << endl;
        //通过子类对象，访问父类同名成员，必须加作用域
}

void test02()  //同名成员函数
{
        Son s;

        //如果子类中出现和父类同名的成员函数，子类的同名成员会隐藏掉父类中所有的同名成员函数

        s.func();  //直接调用，调用的是子类中的同名成员
        s.Base::func();  

    //如果想访问父类中被隐藏的同名成员函数，必须加作用域
        s.Base::func(100);
}

int main()
{
        test02();
}
子类对象可以直接访问到子类中同名成员子类对象加作用域可以访问到父类同名函数当子类和父类拥有同名的成员函数，子类会隐藏父类中同名成员函数，加作用域可以访问到父类中同名函数
