实例：定积分的计算
#include<iostream>
using namespace std;
float function(float x) {
        return 4 / (1 + x * x);
}
class inte {
protected:
        float a, b;//积分区间左右边界
        int n;
        float sum, h;
public:
        inte(float a, float b, int n) {
                this->a = a;
                this->b = b;
                this->n = n;
                sum = 0;
                h = (b - a) / n;
        }
        virtual void integrate(void) = 0;//计算
};
class juxing :public inte {
public:
        juxing(float a, float b, int n):inte(a,b,n) {}
        virtual void integrate(void) {
                float temp = a;
                for (int i = 0; i < n; i++) {
                        sum += function(temp);
                        temp += h;
                }
                cout << sum * h << endl;
        }
};
class tixing :public inte {
public:
        tixing(float a, float b, int n) :inte(a, b, n) {}
        virtual void integrate(void) {
                float temp = a;
                for (int i = 0; i <= n; i++) {
                        sum += function(temp);
                        temp += h;
                }
                sum *= 2;
                sum -= function(a) - function(b);
                sum *= h;
                sum /= 2;
                cout << sum << endl;
        }
};
class simpson :public inte {
public:
        simpson(float a, float b, int n) :inte(a, b, n) {}
        virtual void integrate(void) {
                float tem = a;
                for (int i = 0; i <= n; i++) {
                        if (i % 2 == 0) {
                                sum += 2 * function(tem);
                        }
                        else {
                                sum += 4 * function(tem);
                        }
                        tem += h;
                }
                if (n % 2 == 0) {
                        sum -= (function(a) +function(b));
                }
                else {
                        sum -= (function(a) + 3 * function(b));
                }
                sum *= h;
                sum /= 3;
                cout << sum << endl;
        }
};
        void integrateFunc(inte& p) {
                p.integrate();
        }
        int main() {
                juxing a1(0.0, 1.0, 10);
                tixing a2(0.0, 1.0, 10);
                simpson a3(0.0, 1.0, 10);
                integrateFunc(a1);
                integrateFunc(a2);
                integrateFunc(a3);
                return 0;
        }

#include<iostream>
#include<cmath>  // 用于自定义数学函数（如sin、cos、pow等）
using namespace std;
#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif
// 定义被积函数的函数指针类型：输入float，返回float，简化后续使用
typedef float (*IntegrandFunc)(float);
// 静态默认被积函数：4/(1+x²)（原全局函数，改为静态避免全局污染）
static float defaultFunc(float x) {
    return 4.0f / (1.0f + x * x);
}

// 积分基类：抽象类，封装通用积分属性+可替换被积函数接口
class inte {
protected:
    float a, b;       // 积分区间[a,b]
    int n;            // 等分数
    float sum, h;     // 积分结果、步长
    IntegrandFunc f;  // 函数指针：指向当前被积函数（核心通用接口）
public:
    // 构造函数：支持传入自定义被积函数，默认绑定defaultFunc
    inte(float a, float b, int n, IntegrandFunc func = defaultFunc)
        : a(a), b(b), n(n), f(func) {  // 初始化列表直接初始化所有成员
        sum = 0.0f;
        h = (b - a) / static_cast<float>(n);  // 强制浮点除法，避免精度丢失
    }

    virtual void integrate(void) = 0;  // 纯虚函数：具体积分算法由派生类实现
    virtual ~inte() = default;         // 虚析构：多态场景避免内存泄漏（C++11+）
};

// 矩形法（左矩形）派生类：继承基类，实现具体积分算法
class juxing : public inte {
public:
    // 构造函数：透传参数给基类，默认使用基类的默认函数
    juxing(float a, float b, int n, IntegrandFunc func = defaultFunc)
        : inte(a, b, n, func) {
    }

    // 重写纯虚函数：左矩形法积分逻辑（原逻辑不变，仅将function改为f）
    virtual void integrate(void) override {
        sum = 0.0f;
        float temp = a;
        for (int i = 0; i < n; i++) {
            sum += f(temp);  // 调用函数指针指向的被积函数
            temp += h;
        }
        cout << "矩形法积分结果：\t" << sum * h << endl;
    }
};

// 梯形法派生类：继承基类，实现具体积分算法
class tixing : public inte {
public:
    // 构造函数：透传参数给基类
    tixing(float a, float b, int n, IntegrandFunc func = defaultFunc)
        : inte(a, b, n, func) {
    }

    // 重写纯虚函数：梯形法积分逻辑（修正原符号错误，保证结果正确）
    virtual void integrate(void) override {
        sum = 0.0f;
        float temp = a;
        for (int i = 0; i <= n; i++) {
            sum += f(temp);  // 调用函数指针指向的被积函数
            temp += h;
        }
        // 梯形法标准公式：h/2 * [f(a) + 2*Σ(f(xi)) + f(b)]
        sum = (sum * 2.0f - f(a) - f(b)) * h / 2.0f;
        cout << "梯形法积分结果：\t" << sum << endl;
    }
};

// 辛普森法派生类：继承基类，实现具体积分算法（仅支持偶数等分，保证精度）
class simpson : public inte {
public:
    // 构造函数：透传参数给基类，增加偶数校验（辛普森法核心要求）
    simpson(float a, float b, int n, IntegrandFunc func = defaultFunc)
        : inte(a, b, n, func) {
        // 若n为奇数，自动修正为下一个偶数，保证辛普森公式有效
        if (this->n % 2 != 0) {
            this->n += 1;
            this->h = (this->b - this->a) / static_cast<float>(this->n);
            cout << "辛普森法修正：n需为偶数，自动改为" << this->n << endl;
        }
    }

    // 重写纯虚函数：复合辛普森法积分逻辑（原逻辑不变，调用函数指针）
    virtual void integrate(void) override {
        sum = 0.0f;
        float tem = a;
        for (int i = 0; i <= n; i++) {
            if (i % 2 == 0) {
                sum += 2.0f * f(tem);
            }
            else {
                sum += 4.0f * f(tem);
            }
            tem += h;
        }
        sum -= (f(a) + f(b));  // 修正首末点系数（还原为1）
        sum = sum * h / 3.0f;  // 辛普森标准公式：h/3 * 累加和
        cout << "辛普森法积分结果：\t" << sum << endl;
    }
};

// 多态调用函数：基类引用接收任意派生类对象，通用调用积分方法
void integrateFunc(inte& p) {
    p.integrate();
}

// ------------------- 自定义被积函数示例（可随意添加）-------------------
// 自定义函数1：f(x) = x² （∫0^1 x²dx = 1/3 ≈0.3333333）
float funcX2(float x) {
    return x * x;
}

// 自定义函数2：f(x) = sinx （∫0^π sinx dx = 2）
float funcSinX(float x) {
    return sin(x);  // 需包含<cmath>，x为弧度
}

// 自定义函数3：f(x) = x + 1 （∫0^2 (x+1)dx = 4）
float funcXAdd1(float x) {
    return x + 1.0f;
}

// ------------------- 主函数：测试默认函数+自定义函数 -------------------
int main() {
    cout << "==================== 测试默认函数：4/(1+x²) [0,1]（理论值π≈3.1415926） ====================" << endl;
    juxing a1(0.0f, 1.0f, 10);
    tixing a2(0.0f, 1.0f, 10);
    simpson a3(0.0f, 1.0f, 10);
    integrateFunc(a1);
    integrateFunc(a2);
    integrateFunc(a3);

    cout << "\n==================== 测试自定义函数1：x² [0,1]（理论值1/3≈0.3333333） ====================" << endl;
    juxing b1(0.0f, 1.0f, 10, funcX2);
    tixing b2(0.0f, 1.0f, 10, funcX2);
    simpson b3(0.0f, 1.0f, 10, funcX2);
    integrateFunc(b1);
    integrateFunc(b2);
    integrateFunc(b3);

    cout << "\n==================== 测试自定义函数2：sinx [0,π]（理论值2） ====================" << endl;
    juxing c1(0.0f, M_PI, 100, funcSinX);  // 等分100份提高精度
    tixing c2(0.0f, M_PI, 100, funcSinX);
    simpson c3(0.0f, M_PI, 100, funcSinX);
    integrateFunc(c1);
    integrateFunc(c2);
    integrateFunc(c3);

    cout << "\n==================== 测试自定义函数3：x+1 [0,2]（理论值4） ====================" << endl;
    juxing d1(0.0f, 2.0f, 20, funcXAdd1);
    tixing d2(0.0f, 2.0f, 20, funcXAdd1);
    simpson d3(0.0f, 2.0f, 20, funcXAdd1);
    integrateFunc(d1);
    integrateFunc(d2);
    integrateFunc(d3);

    return 0;
}
