// program 8_6.cpp
#include <iostream>
using namespace std;

class pixel {
    // 类 pixel，表示屏幕像素点
    int x, y;
public:
    // 构造函数一，无参
    pixel() {
        x = 0;
        y = 0;
    }
    // 构造函数二，参数 a、b 表示点的位置
    pixel(int a, int b) {
        x = a;
        y = b;
    }
    // 构造函数三，参数 p 为某个已存在对象
    pixel(const pixel& p) {
        x = p.x;
        y = p.y;
    }
    // 获取对象的 x 值
    int getx() { return x; }
    // 获取对象的 y 值
    int gety() { return y; }
};

// 枚举类型，用于定义颜色常量（名字）
enum colort {
    black, blue, green, cyan, red, magenta, brown,
    lightgray, darkgray, lightblue, lightgreen,
    lightcyan, lightred, lightmagenta, yellow, white, blink
};

// 基类 graphelem（实际为抽象基类）
class graphelem {
protected:
    // 颜色 color
    colort color;
public:
    graphelem(colort col) {
        color = col;
    }
    // 纯虚函数 draw()
    virtual void draw() = 0;
};

// 派生类 line
class line : public graphelem {
    // 成员为 pixel 类对象
    pixel start, end;
public:
    line(pixel sta, pixel en, colort col)
        : graphelem(col), start(sta), end(en) {
    };
    // 虚函数 draw()
    virtual void draw();
};

// 派生类 rectangle
class rectangle : public graphelem {
protected:
    pixel ulcorner, lrcorner;
public:
    rectangle(pixel ul, pixel el, colort col)
        : graphelem(col), ulcorner(ul), lrcorner(el) {
    };
    // 虚函数 draw()
    virtual void draw();
};

// 派生类 circle
class circle : public graphelem {
    // 假设圆心和半径
    pixel center;
    int radius;
public:
    circle(pixel c, int r, colort col)
        : graphelem(col), center(c), radius(r) {
    };
    virtual void draw();
};

// 派生类 square
class square : public rectangle {
public:
    square(pixel ul, int size, colort col)
        : rectangle(ul, pixel(ul.getx() + size, ul.gety() + size), col) {
    };
    virtual void draw();
};

// 派生类 triangle
class triangle : public graphelem {
    pixel p1, p2, p3;
public:
    triangle(pixel a, pixel b, pixel c, colort col)
        : graphelem(col), p1(a), p2(b), p3(c) {
    };
    virtual void draw();
};

// 类 figure，通过它的 paint 函数可“画”出组成一个图形的各图元
class figure {
    // pg 数组含有10个指向基类的指针
    graphelem* pg[10];
public:
    figure(
        graphelem* pg1 = 0, graphelem* pg2 = 0,
        graphelem* pg3 = 0, graphelem* pg4 = 0,
        graphelem* pg5 = 0, graphelem* pg6 = 0,
        graphelem* pg7 = 0, graphelem* pg8 = 0,
        graphelem* pg9 = 0, graphelem* pg10 = 0
    ) {
        pg[0] = pg1; pg[1] = pg2;
        pg[2] = pg3; pg[3] = pg4;
        pg[4] = pg5; pg[5] = pg6;
        pg[6] = pg7; pg[7] = pg8;
        pg[8] = pg9; pg[9] = pg10;
    }
    // 由 paint 成员函数“画”出图形的各图元
    void paint() {
        for (int i = 0; i < 10; i++)
            if (pg[i] != 0)
                pg[i]->draw();
    }
};

// 各派生类的 draw 函数实现（示例输出）
void line::draw() {
    cout << "Draw a " << color << " line from ("
        << start.getx() << "," << start.gety() << ") to ("
        << end.getx() << "," << end.gety() << ")" << endl;
}

void rectangle::draw() {
    cout << "Draw a " << color << " rectangle from ("
        << ulcorner.getx() << "," << ulcorner.gety() << ") to ("
        << lrcorner.getx() << "," << lrcorner.gety() << ")" << endl;
}

void circle::draw() {
    cout << "Draw a " << color << " circle at ("
        << center.getx() << "," << center.gety() << ") with radius " << radius << endl;
}

void square::draw() {
    cout << "Draw a " << color << " square at ("
        << ulcorner.getx() << "," << ulcorner.gety() << ") with size "
        << lrcorner.getx() - ulcorner.getx() << endl;
}

void triangle::draw() {
    cout << "Draw a " << color << " triangle at points ("
        << p1.getx() << "," << p1.gety() << "), ("
        << p2.getx() << "," << p2.gety() << "), ("
        << p3.getx() << "," << p3.gety() << ")" << endl;
}

void main() {
    // 说明个类对象（图元），它们是构成一个图形的九个“部件”
    square sq(pixel(40, 40), 120, black); // 一个正方形
    circle ce1(pixel(100, 100), 50, green); // 两个圆
    circle ce2(pixel(100, 100), 2, blue);
    triangle tr1(pixel(100, 62), pixel(98, 97), pixel(102, 97), blue); // 两个三角形
    triangle tr2(pixel(98, 103), pixel(102, 103), pixel(100, 130), blue);
    rectangle re1(pixel(98, 54), pixel(102, 62), red); // 4 个长方形
    rectangle re2(pixel(98, 138), pixel(102, 146), red);
    rectangle re3(pixel(54, 98), pixel(62, 102), red);
    rectangle re4(pixel(138, 98), pixel(146, 102), red);

    figure fig(&sq, &ce1, &ce2, &re1, &re2, &re3, &re4, &tr1, &tr2);
    fig.paint(); // 调用 paint 函数，“画”出 fig 对象的图元
}
