#include<iostream>
#include<string>
using namespace std;

class File{
        public:
                string filename;
                int filesize;
                int firstcode;

                void getinformation(string name,int size,int code)
                {
                        filename=name;
                        filesize=size;
                        firstcode=code;
                }

                virtual void updatefile()=0;
                virtual void show()=0;
};

class changeencode_name:public File{
        public:
                void updatefile() override{}
                void updatefile(string newname,int newcode)
                {
                        filename=newname;
                        firstcode=newcode;
                }

                void show()
                {
                        string asc;
                        if(firstcode==0){asc="UNICODE";}
                        if(firstcode==1){asc="ASCII";}
                        if(firstcode==2){asc="ANSI";}
                        if(firstcode==3){asc="UTF8";}
                        cout<<"change_encodeAndname:"<<filename<<" "<<filesize<<" "<<asc;
                }
};

class changeencode_size:public File{
        public:
                void updatefile() override{}
                void updatefile(int newsize,int newcode)
                {
                        filesize=newsize;
                        firstcode=newcode;
                }

                void show()
                {
                        string asc;
                        if(firstcode==0){asc="UNICODE";}
                        if(firstcode==1){asc="ASCII";}
                        if(firstcode==2){asc="ANSI";}
                        if(firstcode==3){asc="UTF8";}
                        cout<<"change_encodeAndsize:"<<filename<<" "<<filesize<<" "<<asc;
                }
};



int main()
{
        string name;
        int asize;
        int n;
        char judge;
        cin>>name>>asize>>n;
        cin>>judge;

        changeencode_name f1;
        changeencode_size f2;

        if(judge=='N')
        {
                string changename;
                int code;
                cin>>changename>>code;

                f1.getinformation(name,asize,n);
                f1.updatefile(changename,code); 
                f1.show() ;

        }else{
                if(judge=='S')
                {
                        int changesize;
                    int code;
                cin>>changesize>>code;


                f2.getinformation(name,asize,n); 
                    f2.updatefile(changesize,code) ;
                    f2.show() ;

                }
                else{
                        cout<<"No such operation!";
                        return 0;
                }
        }



}

模板
函数模板
类型参数
代表 “任意数据类型” 的通用占位符，定义在模板头的尖括号中，用于让模板（函数模板 / 类模板）摆脱对具体数据类型的依赖，实现跨类型的代码通用化复用
函数模板定义格式
template <class T1, class T2, ...>  // 多个类型参数用逗号分隔 
返回值类型 函数名(T1 形参1, T2 形参2, ...) { 
 // 不同形参对应不同类型参数
// 函数逻辑（可混合使用T1、T2做运算/声明）
}
带有多个参数的函数模板：使用auto关键字，自动推断函数模板的返回值类型
函数模板参数的默认值可以在定义函数模板时，给出类型参数的默认值，如果未通过实例化给出类型参数值，或者无法推断出类型参数值，则使用该默认的类型参数值
return 表达式; 的规则：表达式算出的值，会自动隐式转换成函数声明的返回值类型，转换失败则编译报错
template <typename TReturn = double, typename T1, typename T2> 
TReturn larger(T1 a, T2 b) 
{ 
   return a > b ? a : b; 
}
