#include<iostream>
using namespace std;
// 1. 类模板：通用数值包装类，T是类模板的类型参数（包装的目标类型）
template<class T>
class MyData {
private:
    T val; // 成员变量，类型为类模板的T
public:
// 2. 类外定义【成员模板函数】copyFrom —— 核心重点
template<class T>        // 第一层：类模板的参数声明（定义T，给MyData<T>用）
template<class U>        // 第二层：成员模板函数自身的参数声明（定义U，独立于T，顺序不可反）
void copyFrom(const U& otherVal) { // 类名限定仅用类的参数T，无需写U
    val = static_cast<T>(otherVal); // 跨类型转换：U→T，保证类型兼容
}
3.类模板中成员函数创建时机
模板调用时才创建。
4.类模版成员函数的类外实现
#include <iostream>
using namespace std;

// 1. 类模板定义
template <typename T>
class MyClass {
private:
    T data;
public:
    // 构造函数声明
    MyClass(T val);

    // 普通成员函数声明
    void setData(T val);
    T getData() const;

    // 重载运算符声明
    MyClass<T> operator+(const MyClass<T>& other);
};

// ========== 类外实现 ==========

// 2. 构造函数类外实现
template <typename T>
MyClass<T>::MyClass(T val) : data(val) {}

// 3. setData 类外实现
template <typename T>
void MyClass<T>::setData(T val) {
    data = val;
}

// 4. getData 类外实现（const 成员函数要保留 const）
template <typename T>
T MyClass<T>::getData() const {
    return data;
}

// 5. 重载 + 运算符类外实现
template <typename T>
MyClass<T> MyClass<T>::operator+(const MyClass<T>& other) {
    return MyClass<T>(data + other.data);
}

// ========== 测试 ==========
int main() {
    MyClass<int> obj1(10);
    MyClass<int> obj2(20);

    MyClass<int> obj3 = obj1 + obj2;

    cout << obj3.getData() << endl; // 输出 30
    return 0;
}
