类模板继承重点强调
子类继承模板父类时，必须指定父类的模板类型 错误：class Son : public Base 正确：class Son : public Base<int>如果子类也是模板，可把自己的模板参数传给父类template<class T> class Son : public Base<T> {}
#include <iostream>
using namespace std;

// 类模板（当作父类）
template <class T>
class Base {
public:
    T m_data;
    void show() {
        cout << "Base: " << m_data << endl;
    }
};
// 子类：必须给父类模板传类型！
class Son : public Base<int> {  // 这里必须写 Base<int>
public:
    void test() {
        m_data = 100;  // 直接用父类成员
    }
};

int main() {
    Son s;
    s.m_data = 10;
    s.show();  // 输出 Base:10
    return 0;
}
// Son 本身也是类模板
template <class T1, class T2>
class Son : public Base<T2> {  // T2 传给父类模板
public:
    T1 m_son;
    void showAll() {
        m_data = 20;    // 父类成员
        m_son = 30;     // 子类成员
        cout << "Son: " << m_son << " Base: " << m_data << endl;
    }
};

int main() {
    // T1=int, T2=double
    Son<int, double> s;
    s.m_data = 3.14;
    s.m_son = 100;
    s.showAll();
    return 0;
}
