stack 容器（栈）
ppt例
//Stack.h
const int maxsize = 6;
class Stack {
    float data[maxsize];
    int top;
public:
    Stack(void);
    ~Stack(void);
    bool empty(void);
    void push(float a);
    float pop(void);
};
//Stack.cpp
#include"Stack.h"
#include<iostream>
using namespace std;

Stack::Stack(void) {
    top = 0;
    cout << "stack initialized." << endl;
}
Stack::~Stack(void) {
    cout << "stack destroyed." << endl;
}
bool Stack::empty(void) {
    return top == 0 ? true : false;
}
void Stack::push(float a) {
    if (top == maxsize) {
        cout << "stack is full!" << endl;
        return;
    }
    data[top] = a;
    top++;
}
float Stack::pop(void) {
    if (top == 0) {
        cout << "Stack is underflow!" << endl;
        return 0;
    }
    top--;
    return data[top];
}
//Main.cpp
#include"Stack.h"
#include<iostream>
using namespace std;

int main() {
    Stack s1, s2;
    int i;
    //第一组入栈：2 4 6 8 10 12
    for(i = 1;i <= maxsize;i++)
        s1.push(2 * i);
    //全部出栈打印：12 10 8 6 4 2
    for(i = 1;i <= maxsize;i++)
        cout<<s1.pop()<<" ";
    //第二组入栈：2.5 5 7.5 10 12.5 15
    for(i = 1;i <= maxsize;i++)
        s1.push(2.5*i);
    //s1出栈→s2入栈
    for(i = 1;i <= maxsize;i++)
        s2.push(s1.pop());
    cout << endl;
    //s2全部出栈打印
    do
        cout << s2.pop() << " ";
    while (!(s2.empty()));
    cout << endl;
    return 0;
}
