迭代器
想象一下你有一本书（容器），你想一页一页地读它（遍历）。迭代器就像是书签或手指，它帮你记录当前读到哪一页，并且可以：
· 翻到下一页（++）
· 翻到前一页（--）
· 跳转到某一页（+ n）
· 检查是不是最后一页（判断是否到达结尾）
#include <vector>
#include <iostream>
using namespace std;

int main() {
    vector<int> nums = {1, 2, 3, 4, 5};  // 容器：像一列火车

    // 迭代器：像火车上的检票员，可以一节车厢一节车厢移动
    auto it = nums.begin();  // 站到第一节车厢门口

    while (it != nums.end()) {  // 只要没到最后一节车厢后面
        cout << *it << " ";     // 查看当前车厢的乘客（数据）
        ++it;                   // 走到下一节车厢
    }
    // 输出：1 2 3 4 5
}
迭代器的类型（不同功能的"书签"）
输入迭代器：只能读，不能写（像只读的扫描仪）输出迭代器：只能写，不能读（像只能刻录的光盘）前向迭代器：只能向前走（像单行道的车）双向迭代器：可以前进和后退（像双向行驶的车）随机访问迭代器：可以随意跳转（像直升机，想去哪去哪）
vector<int> vec;          // 随机访问迭代器（最强）
list<int> lst;            // 双向迭代器
forward_list<int> flst;   // 前向迭代器
set<int> s;               // 双向迭代器
map<string, int> m;       // 双向迭代器
迭代器的基本操作
vector<int> v = {10, 20, 30, 40, 50};

// 获取迭代器
auto begin_it = v.begin();  // 指向第一个元素
auto end_it = v.end();      // 指向最后一个元素的后面

// 访问元素
cout << *begin_it;          // 输出10（解引用，像指针）

// 移动迭代器
++begin_it;                 // 前进到下一个位置
--begin_it;                 // 后退到前一个位置（如果是双向迭代器）
begin_it += 3;              // 直接跳3个位置（如果是随机访问迭代器）

// 比较迭代器
if (begin_it != end_it) {
    // 还没到结尾
}

// 使用范围for循环（底层就是迭代器）
for (int num : v) {
    cout << num << " ";
}
// 等价于：
for (auto it = v.begin(); it != v.end(); ++it) {
    cout << *it << " ";
}
实际应用场景
场景1：删除特定元素
vector<int> nums = {1, 2, 3, 4, 5, 3, 6};

// 删除所有等于3的元素
for (auto it = nums.begin(); it != nums.end(); ) {
    if (*it == 3) {
        it = nums.erase(it);  // 删除元素，返回下一个位置的迭代器
    } else {
        ++it;
    }
}
场景2：在特定位置插入
list<string> names = {"Alice", "Charlie", "David"};

// 在Charlie前面插入Bob
auto it = find(names.begin(), names.end(), "Charlie");
if (it != names.end()) {
    names.insert(it, "Bob");
}
