put() get()
从键盘输入任一个字符串，通过put将其写到自定义磁盘文件“putgetfile.txt”中，而后再使用get从该文件中读出所写串并显示在屏幕上
#include <fstream.h>
#include <stdio.h> 
void main() {        
//键盘输入字符串，通过put将其写到自定义磁盘文件中
        char str[80];
        cout<<"Input string:"<<endl;
        gets(str);
        ofstream fout("putgetfile.txt");         
        int i=0;
        while ( str[i] ) 
              fout.put(str[i++]); 
        fout.close();
        cout<<“--------------------”<<endl;//而后使用get从文件中读出该串显示在屏幕上
        char ch;
        ifstream fin("putgetfile.txt");  
        fin.get(ch);
        while(!fin.eof()){
        //从头读到文件结束(当前符号非文件结束符时继续)
        //注: 成员函数eof()在读到文件结束时方返回true
              cout<<ch;
              fin.get(ch);
        }
        cout<<endl;
        fin.close();
}

