程序设计
电影《2012》中提到的历法来自于玛雅文明。玛雅文明是最早发明、使用历法的文明之一。玛雅人日常生活使用的是哈布历（Haab’）。哈布历规定一年365天，分为19个月，前18个月每月20天，第19个月5天。玛雅文明还使用一种用于宗教祭祀的卓尔金历（Tzolk'in，就是这个历法预言2012年的灾难）。卓尔金历规定一年260天，分为13个月，每个月20天。哈布历和卓尔金历的公元0年1月1日是同一天开始的（考古学家认为是公元前3114年8月31日），请编写一个程序实现哈布历和卓尔金历的相互转换，要求：
如果输入一组（至少5个）哈布历日期，将其转换为卓尔金历日期（日期以日 月 年的顺序表示），并按照日期由小到大的顺序输出
如果输入一组（至少5个）卓尔金历日期，将其转换为哈布历日期（日期以日 月 年的顺序表示），并按照日期由小到大的顺序输出
#include <iostream>
using namespace std;
const int N = 5;
struct date {
        int year;
        int month;
        int day;
}calendar[N];
void sort_calendar(date[], int);
void swap(date&, date&);
int main() {
        char ch;
        int day, mon, year;
        long sum;
        cout << "please input catelog of calendar : ";
        cin >> ch;
    if ((ch == 'H') || (ch == 'h')) {//哈布历法
        for (int i = 0; i < N; i++) {
            cin >> calendar[i].day >> calendar[i].month >> calendar[i].year;
            day = calendar[i].day ;
            mon = calendar[i].month - 1;
            year = calendar[i].year;
            sum = day + mon * 20 + year * 365;
            year = sum / 260;
            sum = sum % 260;
            mon = sum / 20 + 1;
            day = sum % 20 ;
            calendar[i].day = day;
            calendar[i].month = mon;
            calendar[i].year = year;
        }
        cout << "Output calendar of Tzolk‘in" << endl;
    }
    else {
        if ((ch == 'T') || (ch == 't')) {
            for (int i = 0; i < N; i++) {
                cin >> calendar[i].day >> calendar[i].month >> calendar[i].year;
                day = calendar[i].day - 1;
                mon = calendar[i].month - 1;
                year = calendar[i].year;
                sum = day + mon * 20 + year * 260;
                year = sum / 365;
                sum = sum % 365;
                mon = sum / 20 + 1;
                day = sum % 20 + 1;
                calendar[i].day = day;
                calendar[i].month = mon;
                calendar[i].year = year;
            }
            cout << "Output calendar of Haab'" << endl;
        }
        else
            cout << "input error" << endl;
    }
    sort_calendar(calendar, N);//日期排序
    for (int i = 0; i < N; i++)//结果输出
        cout << calendar[i].day << " " << calendar[i].month << " " << calendar[i].year << endl;
}
void sort_calendar(date d[], int n) {
    for (int i = 0; i < n; i++)
        for (int j = n - 1; j > i; j--)
            if (d[j].year < d[j - 1].year)
                swap(d[j], d[j - 1]);
            else
                if (d[j].year == d[j - 1].year)
                    if (d[j].month < d[j - 1].month)
                        swap(d[j], d[j - 1]);
                    else
                        if (d[j].month == d[j - 1].month)
                            if (d[j].day < d[j - 1].day)
                                swap(d[j], d[j - 1]);
}//交换函数定义略
void swap(date& a, date& b) {
    // 定义临时变量存储a的内容，避免交换时数据覆盖
    date temp;
    temp.year = a.year;
    temp.month = a.month;
    temp.day = a.day;

    // 将b的值赋给a
    a.year = b.year;
    a.month = b.month;
    a.day = b.day;

    // 将临时变量（原a）的值赋给b
    b.year = temp.year;
    b.month = temp.month;
    b.day = temp.day;
} 
1742年6月7日，哥德巴赫写信给欧拉，提出了以下猜想：任何一个大于等于6的偶数都可以表示成为两个奇素数之和；任何一个大于等于9的奇数都可以表示成为三个奇素数之和——这就是著名的哥德巴赫猜想。
请编写程序验证在10000以内哥德巴赫猜想是否成立。如果成立输出Yes否则输出No
#include<iostream>
using namespace std;
bool isprime(int n) {
        if (n < 2) {
                return false;
        }
        for (int i = 2; i * i <= n; i++) {
                if (n % i == 0) {
                        return false;
                }
        }
        return true;
}

bool even(int n) {
        //判定一个大于等于6的偶数是否符合哥德巴赫猜想
        for (int i = 3; i <= n - 3; i += 2) {
                if (isprime(i) && isprime(n - i)) {
                        return true;
                }
        }
        return false;
}
bool odd(int n) {
        //判定一个大于等于9的奇数是否符合哥德巴赫猜想
        for (int i = 3; i <= n - 3; i += 2) {
                if (isprime(i) && even(n - i)) {
                        return true;
                }
        }
        return false;
}
int main() {        //主程序 在6到10000，9到10000做循环分别判定偶数和奇数
        bool g1 = true, g2 = true;
        for (int i = 6; i <= 10000; i += 2)
                g1 = g1 && even(i);
        for (int i = 9; i <= 10000; i += 2)
                g2 = g2 && odd(i);

        if (g1 && g2)
                cout << "Yes" << endl;
        else
                cout << "No" << endl;
}

补码
二进制负数的存储形式 = 补码
原码：最高位为符号位（0 = 正，1 = 负），其余位为数值的绝对值的二进制形式。
例：+5 原码00000101；-5 原码10000101。
反码：
正数反码 = 原码（符号位 + 数值位都不变）；
负数反码 = 符号位不变，数值位按位取反。
例：+5 反码00000101；-5 反码11111010。
补码：
正数补码 = 原码（符号位 + 数值位都不变）；
负数补码 = 负数反码 + 1（符号位不变，仅数值位参与运算）。
例：+5 补码00000101；-5 补码11111011。
二、三者的核心关系
正数：三者完全相同
对于正数（符号位为 0），原码、反码、补码的二进制形式完全一致，没有任何差异。例：+7（8 位）
原码：00000111
反码：00000111
补码：00000111
负数：补码 = 反码 + 1，反码 = 原码（数值位取反）
对于负数（符号位为 1），三者的转换关系是原码→反码→补码，每一步都保持符号位不变：
第一步：原码转反码 → 符号位不变，数值位取反；
第二步：反码转补码 → 符号位不变，数值位 + 1；
反向转换（补码转原码）：补码 - 1→数值位取反，符号位不变（与原码转补码的步骤逆序）。
例：-7（8 位）
原码：10000111
反码：11111000（原码数值位取反）
补码：11111001（反码 + 1）

十进制负数转二进制
绝对值二进制+补齐0+全部取反（反码）+加一（补码）简化版
绝对值二进制+补齐0+符号位改为1(首位变为一)+取反（反码）+加一（补码）
取-7的绝对值7，转成 8 位二进制原码：0000 0111；
将-7的原码（符号位改为 1）1000 0111按位取反，得到反码：1111 1000；
原码转反码时，仅对表示数值大小的 “数值位” 按位取反，作为标记的 “符号位” 保持不变。
给反码末位加 1（1111 1000 + 1 = 1111 1001），最终1111 1001就是-7的 8 位二进制补码（即计算机存储-7的二进制形式）。
要解决 “将 32 位二进制数转换为补码并输出” 的问题，首先要明确补码的核心规则：
若二进制数的最高位（符号位）是0（正数），其补码与原码完全相同；若最高位是1（负数），其补码需通过 “按位取反（符号位也参与） + 末位加 1” 得到。
解题思路
输入 32 位二进制数：用长度为 32 的数组array[]存储每一位（0或1）；判断正负：检查数组的第 0 位（最高位，符号位）：
若第 0 位是0：补码 = 原码，直接输出数组；若第 0 位是1：执行 “按位取反 + 末位加 1” 得到补码；
实现补码转换（负数）：
步骤 1：对数组中所有位（0~31 位）按位取反（0变1，1变0）；步骤 2：从数组的最后一位（第 31 位，最低位）开始加 1，处理进位（逢 2 进 1）；
输出补码：遍历数组，打印每一位。

#include <iostream>
using namespace std;// 关键转换函数：将32位二进制数数组转换为补码
void exchange(int array[]) {// 步骤1：判断符号位（最高位是array[0]）
   if (array[0] == 1) { 
// 负数，需要转换为补码
// 子步骤1：按位取反（所有位0变1、1变0）
   for (int i = 0; i < 32; i++) {
            array[i] = 1 - array[i]; 
            // 0→1，1→0
            }
            // 子步骤2：末位加1，处理进位
            int carry = 1; // 初始进位为1
            for (int i = 31; i >= 0; i--) { 
            // 从最低位（第31位）开始加
            int sum = array[i] + carry;
            array[i] = sum % 2; // 当前位结果（0或1）
            carry = sum / 2;   // 更新进位（0或1）
            if (carry == 0) {  // 无进位时，提前结束
            break;
            }
            }
            }// 正数：补码=原码，无需处理}
            int main() {
            int array[32];
    cout << "请输入32位二进制数（每一位输入0或1，共32个）：" << endl;
    for (int i = 0; i < 32; i++) {
        cin >> array[i];// 简单校验输入合法性（仅允许0或1）
        if (array[i] != 0 && array[i] != 1) {
            cout << "输入错误，仅允许输入0或1！" << endl;
            return 1;
            }
            }// 调用转换函数得到补码
            exchange(array);// 输出补码
    cout << "转换后的补码为：" << endl;
    for (int i = 0; i < 32; i++) {
        cout << array[i];// 每8位空一格，方便查看
        if ((i + 1) % 8 == 0) {
            cout << " ";}}
    cout << endl;
    return 0;
    }
