#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// 分解单个数字x的质因数，返回展开的质因数列表
vector<int> factorize(int x) {
    vector<int> factors;
    if (x < 2) return factors; // 1没有质因数
    for (int i = 2; i <= x; ++i) {
        while (x % i == 0) { // 反复除以i，直到不能整除
            factors.push_back(i);
            x /= i;
        }
    }
    return factors;
}
// 获取n!的质因数展开列表
vector<int> factorialFactors(int n) {
    vector<int> res;
    for (int i = 2; i <= n; ++i) { // 1的质因数为空，从2开始
        vector<int> temp = factorize(i);
        res.insert(res.end(), temp.begin(), temp.end());
    }
    return res;
}

int main() {
    int a, b;
    cin >> a >> b;
    // 获取a!和b!的质因数列表
    vector<int> factorsA = factorialFactors(a);
    vector<int> factorsB = factorialFactors(b);
    // 合并两个列表
    vector<int> totalFactors = factorsA;
    totalFactors.insert(totalFactors.end(), factorsB.begin(), factorsB.end());
    // 排序（保证质因数从小到大）
    sort(totalFactors.begin(), totalFactors.end());

    // 按格式输出
    for (int i = 0; i < totalFactors.size(); ++i) {
        if (i > 0) {
            cout << "*";
        }
        cout << totalFactors[i];
    }
    cout << endl;  
    return 0;
}
