vector<int> factorize(int x)： 是 C++ 中的函数声明，用于定义一个名为 factorize 的函数
各部分含义
vector<int>：函数的返回值类型，表示该函数执行后会返回一个存储int类型元素的vector容器（可理解为 “整数列表”）。这里的vector是 C++ 标准库中的动态数组容器，<int>指定容器中元素的类型为整数。
factorize：函数的名称，调用函数时通过这个名称标识。
(int x)：函数的参数列表，表示调用该函数时需要传入一个int类型的参数，参数名为x（通常用于接收需要分解质因数的整数）。
结合功能理解
结合之前的代码逻辑，这个函数声明的完整含义是：定义一个名为factorize的函数，接收一个整数x作为输入，返回一个存储x的所有质因数的整数列表（vector<int>）。
例如，调用factorize(12)会返回包含[2, 2, 3]的vector<int>，调用factorize(7)会返回包含[7]的vector<int>
if (x < 2) return factors;
if (x < 2)：判断输入的数是否小于 2（覆盖x=0、x=1、负数等情况）；
return factors;：直接返回空的factors向量（因为这些数没有质因数，无需分解）
 for (int i = 2; i <= x; ++i) {
        while (x % i == 0) { // 反复除以i，直到不能整除
            factors.push_back(i);
            x /= i;
        }
i从 2 开始遍历，是否会出现用合数作为除数的情况？
答案是：不会影响结果，因为合数的因数已经被更小的质数提前分解过了，此时x不可能被合数整除。
详细解释：
假设i遍历到一个合数（比如 4），此时x已经被 2、3 等更小的质数分解过了 —— 如果x能被 4 整除，那它必然能被 2 整除（因为 4=2×2），但在i=2的循环中，x已经被反复除以 2，直到无法整除为止。
因此，当i遍历到合数时，x % i == 0的条件永远不会成立，自然不会执行while循环内的分解逻辑。
factors.push_back(i);
factors.push_back(i); 是 C++ 中 vector 容器的成员函数调用，作用是将元素 i 添加到 factors 这个动态数组的末尾。下面从语法、作用、使用场景三方面详细解释：
为什么用while而不用for呢
在质因数分解的逻辑中使用 while 而非 for，是由 “需要反复用同一个因数分解当前数” 的需求决定的 ——while 更适合处理这种 “条件满足时重复执行” 的场景，而 for 更适合 “已知循环次数” 的遍历。下面具体解释：
若强行用 for 替代 while，需要额外控制循环条件，代码会变得冗余且不直观。例如：
// 用for模拟while的逻辑（不推荐）
for (; x % i == 0; x /= i) {factors.push_back(i);}
虽然语法上可行，但 for 的初始化 / 递增部分为空，完全失去了 for 循环 “遍历固定次数” 的设计初衷，可读性反而变差。
   vector<int> temp = factorize(i);
虽然factorize函数返回的是一个vector ，但是它没有标记，不好处理，所以在每次循环中都创建一个vector容器。便于使用和操控。
方案二
#include<iostream>
#include<vector>
using namespace std;

int fun1(int m)
{
    if (m == 1 || m == 0) { return 1; }
    else
    {
        return m * fun1(m - 1);
    }
}
int fun2(int x, int y)
{
    int z = fun1(x) * fun1(y);
    return z;
}

int main()
{
    int a, b, total;
    cin >> a >> b;
    total = fun2(a, b);
    int i, j;
    vector<int> vec;
    for (i = 2; i <= total; i++)
    {
        if (total % i == 0)
        {
            vec.push_back(i);
            total /= i;
            i--;
        }
    }
    int sum = vec.size();
    for (j = 0; j <= sum - 2; j++)
    {
        cout << vec[j] << "*";
    }
    cout << vec[sum - 1] << endl;
}
#include <iostream>   
#include <vector>    
using namespace std;  
// 计算质数p在n!中的幂次
int countPrimePower(int p, int n) {
    int cnt = 0;  // 初始化幂次计数器为0
    while (n > 0) {  // 循环直到n被除到0为止
        n /= p;      // n = n / p（取整），对应公式中的⌊n/p^k⌋
        cnt += n;    // 累加每一步的结果，得到总幂次
    }
    return cnt;  // 返回质数p在n!中的总幂次
}
// 判断一个数是否为质数
bool isPrime(int num) {
    if (num < 2) return false;  // 小于2的数不是质数
    // 遍历从2到√num的所有数，检查是否能整除num
    for (int i = 2; i * i <= num; ++i) {
        if (num % i == 0) return false;  // 能被整除则不是质数
    }
    return true;  // 否则是质数
}
int main() {
    int a, b;  // 定义输入变量a和b
    cin >> a >> b;  // 从控制台输入两个整数a和b
    int max_num = max(a, b);  // 获取a和b的最大值，确定质数枚举范围
    vector<pair<int, int>> factors; // 定义向量，存储<质数, 幂次>键值对
        // 枚举所有质数，计算其在a!*b!中的总幂次
    for (int p = 2; p <= max_num; ++p) {  // 从2枚举到max_num（质数最大不超过max(a,b)）
        if (isPrime(p)) {  // 如果p是质数
            // 计算p在a!中的幂次 + p在b!中的幂次 = 总幂次
            int power = countPrimePower(p, a) + countPrimePower(p, b);
            if (power > 0) {  // 若幂次大于0（避免无效存储）
                factors.push_back({p, power});  // 将<质数, 幂次>存入向量
            }
        }
    }
        // 按格式输出质因数分解结果
    for (int i = 0; i < factors.size(); ++i) {  // 遍历每个<质数, 幂次>对
        int p = factors[i].first;    // 获取当前质数
        int power = factors[i].second;  // 获取当前质数的幂次
        for (int j = 0; j < power; ++j) {  // 按幂次重复输出质数
            // 判断是否是最后一个质数的最后一次输出
            if (i == factors.size() - 1 && j == power - 1) {
                cout << p;  // 最后一个数，不加*
            } else {
                cout << p << "*";  // 非最后一个数，加*分隔
            }
        }
    }
    cout << endl;  // 输出换行，结束
    return 0;  // 程序正常结束
}
题目描述
编写一个 C++ 程序，实现对非负整数 n 的阶乘（n!）进行质因数分解，并按指定格式输出分解结果。要求：
程序不得使用任何 STL 组件（如 vector、string、algorithm 头文件中的算法等），仅允许使用 C++ 基础语法（数组、循环、条件判断、<iostream>头文件）；
质因数分解规则：将 n! 分解为 “质数 ^ 次数” 的乘积形式，次数为 1 时省略 “^1”，多个质因数之间用 “ × ” 分隔；
边界处理：
若输入 n 为负数，输出 “阶乘仅支持非负整数！”；
若 n=0 或 n=1，输出 “0! = 1” 或 “1! = 1”；
质因数筛选要求：高效筛选 1~n 之间的所有质数，统计每个质数在 n! 中出现的总次数（需使用公式：次数 = ⌊n/p⌋ + ⌊n/p²⌋ + ⌊n/p³⌋ + … 直到 p^k > n），禁止暴力计算阶乘后再分解（避免数值溢出）。
输入格式
输入一个整数 n（0 ≤ n ≤ 10000）。
输出格式
若 n 为负数：输出 “阶乘仅支持非负整数！”；
若 n=0 或 n=1：输出 “n! = 1”；
其他情况：输出 “n! = p1^k1 × p2^k2 × ... × pm^km”（次数为 1 时仅输出质数，如 5! = 2^3 × 3 × 5）。
输入输出示例
示例 1
输入：5输出：5! = 2^3 × 3 × 5
示例 2
输入：10输出：10! = 2^8 × 3^4 × 5^2 × 7
示例 3
输入：1输出：1! = 1
示例 4
输入：-3输出：阶乘仅支持非负整数！
示例 5
输入：0输出：0! = 1
解题要求
必须实现isPrime函数判断质数，优化遍历范围至√num；
用数组存储质数和对应次数，替代 STL 的 vector；
严格遵循输出格式（分隔符、次数显示规则、换行等）；
代码结构清晰，包含核心功能函数factorizeFactorial，主函数负责输入和调用。
#include <iostream>
using namespace std;
// 函数：判断一个数是否为质数（辅助筛法，也可单独用）
bool isPrime(int num) {
    if (num < 2) return false; // 小于2的数不是质数
    for (int i = 2; i * i <= num; i++) { // 优化：只需遍历到√num
        if (num % i == 0) return false;
    }
    return true;
}

// 函数：计算n!的质因数分解（无STL）
void factorizeFactorial(int n) {
    if (n < 0) {
        cout << "阶乘仅支持非负整数！" << endl;
        return;
    }
    if (n == 0 || n == 1) {
        cout << n << "! = 1" << endl; // 0!和1!都是1，无质因数
        return;
    }

    // 步骤1：筛选1~n的所有质数
    int primes[10000]; // 假设n不超过10000，足够存储质数
    int primeCount = 0; // 记录质数的个数
    for (int i = 2; i <= n; i++) {
        if (isPrime(i)) {
            primes[primeCount++] = i; // 找到质数就存入数组
        }
    }

    // 步骤2：统计每个质数在n!中的次数
    int counts[10000] = { 0 }; // 存储每个质数的次数，初始化为0
    for (int i = 0; i < primeCount; i++) {
        int p = primes[i];
        int total = 0;
        int temp = n;
        while (temp > 0) {
            temp /= p;
            total += temp;
        }
        counts[i] = total;
    }

    // 步骤3：输出分解结果（格式：n! = p1^k1 × p2^k2 × ...）
    cout << n << "! = ";
    for (int i = 0; i < primeCount; i++) {
        cout << primes[i];
        if (counts[i] > 1) { // 次数>1时输出^k
            cout << "^" << counts[i];
        }
        if (i != primeCount - 1) { // 非最后一个质数，输出×
            cout << " × ";
        }
    }
    cout << endl;
}

int main() {
    int n;
    cout << "请输入要求阶乘质因数分解的数：";
    cin >> n;
    factorizeFactorial(n);
    return 0;
}
