杨辉三角

#include <iostream>
#include <vector>
using namespace std;

// 函数功能：生成并打印n阶杨辉三角
// 参数n：杨辉三角的行数（用户输入的正整数）
void yanghui(int n) {
    // 初始化二维vector：(n+4)行 × (n+4)列，所有元素默认值为0
    // 额外多分配4行4列是为了避免边界访问风险（无需精确计算行列上限，简单直接）
    vector<vector<int>> res(n + 4, vector<int>(n + 4));
    // 第一步：填充每行的第一个元素（第0列）为1
    // 杨辉三角特性：每行首尾元素均为1，第0列是所有行的首元素
    for (int i = 0; i <= n - 1; i++) {  // i遍历所有行（0到n-1，共n行）
        res[i][0] = 1;                  // 第i行第0列赋值为1
    }

    // 第二步：填充每行的最后一个元素（对角线位置）为1
    // 第i行的最后一个元素索引是i（因为第i行有i+1个元素，索引0~i）
    for (int i = 1; i <= n - 1; i++) {  // i从1开始（第0行只有1个元素，已在第一步赋值）
        res[i][i] = 1;                  // 第i行第i列（对角线）赋值为1
    }

    // 第三步：计算每行的中间元素（核心逻辑）
    // 中间元素 = 上一行前一列元素 + 上一行当前列元素
    for (int i = 2; i <= n - 1; i++) {  // i从2开始（第0、1行无中间元素，已完整填充）
        // j遍历当前行的中间列（1到i-1，跳过首尾的1）
        for (int j = 1; j <= i - 1; j++) {
            res[i][j] = res[i - 1][j] + res[i - 1][j - 1];  // 杨辉三角核心公式
        }
    }

    // 第四步：打印杨辉三角
    for (int i = 0; i <= n - 1; i++) {  // 遍历每一行
        // 只打印当前行的有效元素（0到i列，共i+1个元素）
        for (int j = 0; j <= i; j++) {
            cout << res[i][j] << " ";  // 元素间用空格分隔，提升可读性
        }
        cout << endl;  // 一行打印完毕，换行
    }
}

int main() {
    int m;               
    cin >> m;            
    yanghui(m);           // 调用函数，生成并打印m阶杨辉三角
    return 0;            
}
#include <iostream>
#include <vector>
using namespace std;

// 生成n阶杨辉三角的函数，返回二维vector存储结果
vector<vector<int>> generateYanghui(int n) {
    // 初始化n行的二维vector，每行初始为空
    vector<vector<int>> triangle(n);

    for (int i = 0; i < n; ++i) {
        // 第i行有i+1个元素，先全部初始化为1（满足首尾为1的特性）
        triangle[i].resize(i + 1, 1);

        // 计算中间元素（从第2行开始，i≥2）
        for (int j = 1; j < i; ++j) {
            triangle[i][j] = triangle[i-1][j-1] + triangle[i-1][j];
        }
    }
    return triangle;
}

int main() {
    int n;
    cin >> n;  // 输入行数

    // 调用函数生成杨辉三角
    vector<vector<int>> result = generateYanghui(n);

    // 输出结果（匹配样例格式，元素间空格分隔）
    for (const auto& row : result) {
        for (int num : row) {
            cout << num << " ";
        }
        cout << endl;
    }

    return 0;
}

