strcat_s（）函数
这个函数没用到引用，却能修改主函数里的数组a，核心原因是：数组名作为函数参数时，会自动 “退化为指向数组首元素的指针”—— 传递的不是数组拷贝，而是数组的内存地址，函数内通过地址直接操作原数组内存。
#include<iostream>
using namespace std;
void strcat(char s[], char ct[])
{
        int i = 0, j = 0;
        while (s[i] != 0)
                i++;
   // 第一步：找到字符串s的末尾（'\0'的位置）
   // '\0'是C风格字符串的结束标志，ASCII码值为0，所以s[i] != 0等价于s[i] != '\0'
        while (ct[j] != 0)
                s[i++] = ct[j++];
 // 把ct[j]赋值给s[i]，然后i、j同时自增（先赋值，后自增）
        s[i] = '\0';
        //给拼接后的s添加结束符'\0'
        // 否则cout打印时会超出数组范围，输出乱码
}
int main() {
        char a[40] = "李明";
        char b[20] = "是南开大学学生";
                strcat(a, b);//实参为数组名
        cout << a << endl;//打印字符数组a
        return 0;
}
