用指针排序字符串
设计一个字符指针数组name，将该数组的元素按照第一个字母的ASCII码由小到大排序，如果第一个字母相同，则按第二个字母排序，以此类推。
#include <iostream>
#include <cstring> // 包含strcmp函数
using namespace std;
int main() {
    // 1. 定义并初始化字符指针数组（存储待排序的字符串）
    char* name[] = {"Zhang", "Gao", "Tang", "Wang", "Li", "Gou", "Zhao"};
    // 计算数组长度（元素个数）
    int len = sizeof(name) / sizeof(name[0]);
    // 2. 冒泡排序：按ASCII码逐字符升序排列
    for (int i = 0; i < len - 1; i++) { // 外层循环：控制排序轮数
        for (int j = 0; j < len - 1 - i; j++) { // 内层循环：每轮比较次数
            // strcmp(a,b)：a>b返回正数，a==b返回0，a<b返回负数
            // 若name[j] > name[j+1]，交换指针指向（升序）
            if (strcmp(name[j], name[j+1]) > 0) {
                char* temp = name[j];
                name[j] = name[j+1];
                name[j+1] = temp;
            }
        }
    }

    // 3. 输出排序结果
    cout << "排序后的字符串：" << endl;
    for (int i = 0; i < len; i++) {
        cout << name[i] << endl;
    }

    return 0;
}
#include <iostream>
#include <cstring>
#include <algorithm> // 包含sort函数
using namespace std;

int main() {
    char* name[] = {"Zhang", "Gao", "Tang", "Wang", "Li", "Gou", "Zhao"};
    int len = sizeof(name) / sizeof(name[0]);

    // sort算法 + Lambda表达式：自定义比较规则（升序）
    sort(name, name + len, [](const char* a, const char* b) {
        // strcmp(a,b) < 0 表示a的ASCII码小于b，a应排在b前面
        return strcmp(a, b) < 0;
    });

    // 输出结果
    cout << "排序后的字符串：" << endl;
    for (int i = 0; i < len; i++) {
        cout << name[i] << endl;
    }

    return 0;
}
