#include <iostream>
#include <cmath>  // 用于exp等数学函数
using namespace std;

// 定积分计算函数（梯形法）
// 参数：a-积分下限，b-积分上限，fun-被积函数指针
double integral(double a, double b, double (*fun)(double)) {
    // 梯形法：将区间[a,b]分成n个小区间，n越大精度越高
    const int n = 100000;  // 区间分割数（可调整）
    double h = (b - a) / n;  // 每个小区间的宽度
    double sum = 0.5 * (fun(a) + fun(b));  // 首尾项的平均

    // 累加中间点的函数值
    for (int i = 1; i < n; ++i) {
        double x = a + i * h;
        sum += fun(x);
    }
    return sum * h;  // 梯形法公式：h * (sum)
}


// 被积函数1：f(x) = 1 + x
double f1(double x) {
    return 1 + x;
}

// 被积函数2：f(x) = 2x + 3
double f2(double x) {
    return 2 * x + 3;
}

// 被积函数3：f(x) = e^x + 1
double f3(double x) {
    return exp(x) + 1;
}

// 被积函数4：f(x) = (1 + x)^2
double f4(double x) {
    return (1 + x) * (1 + x);
}

// 被积函数5：f(x) = x^3
double f5(double x) {
    return pow(x, 3);
}


int main() {
    double a, b;
    cout << "请输入积分下限a和上限b（用空格分隔）：";
    cin >> a >> b;

    // 计算并输出5个定积分的结果
    cout << "∫(" << a << "," << b << ") (1+x)dx = " << integral(a, b, f1) << endl;
    cout << "∫(" << a << "," << b << ") (2x+3)dx = " << integral(a, b, f2) << endl;
    cout << "∫(" << a << "," << b << ") (e^x+1)dx = " << integral(a, b, f3) << endl;
    cout << "∫(" << a << "," << b << ") (1+x)^2dx = " << integral(a, b, f4) << endl;
    cout << "∫(" << a << "," << b << ") x^3dx = " << integral(a, b, f5) << endl;

    return 0;
}
