模拟题2转换字符

数字字符：'0'=48 < '1'=49 < ... < '9'=57
大写字母：'A'=65 < 'B'=66 < ... < 'Z'=90
小写字母：'a'=97 < 'b'=98 < ... < 'z'=122
空格：' '=32（比数字、字母都小）
小写字母 → 转大写（ASCII 减 32）
字符类型(char)可以直接比较大小
#include<iostream>
#include<string>
#include<cctype> // 包含 isalpha() 函数
using namespace std;

int main() {
    string str;
    getline(cin, str); // 支持输入含空格的字符串（比如 "abc 123 def"）

    for (size_t i = 0; i < str.size(); i++) {
        if (!isalpha(str[i])) { // isalpha(c)：判断 c 是否为字母（大小写都算）
            str[i] = ' '; // 非字母 → 空格
        } else if (islower(str[i])) { // islower(c)：判断 c 是否为小写字母
            str[i] = toupper(str[i]); // toupper(c)：将小写字母转大写（自带判断，更安全）
        }
        // 大写字母无需处理，直接保留
    }

    cout << str << endl;
    return 0;
}

#include<iostream>
#include<string>
using namespace std;
int main() {
    string str;
    getline(cin, str); // 支持输入含空格的字符串（比如 "abc 123 def"）
    // 遍历字符串每个字符
    for (size_t i = 0; i < str.size(); i++) 
    {
        char c = str[i];
        // 直接判断：既不是大写字母，也不是小写字母 → 非字母||或是并集@是交集借助维恩图理解；
        if ((c < 'A' || c > 'Z') && (c < 'a' || c > 'z')) 
        {
            str[i] = ' '; // 替换为空格
        }

        // 2. 判断是否为小写字母 → 转大写（ASCII 减 32）
        else if (c >= 'a' && c <= 'z') {
            str[i] = c - 32; // 例如 'a'(97)-32=65='A'
        }
        // 3. 大写字母无需处理，直接保留
    }

    cout << str << endl;
    return 0;
}
