#include <iostream>
#include <cstring> // 用于字符串复制
using namespace std;

// 定义选手结构体
struct Player 
{
    char name[50]; // 存储姓名（原生字符数组，不使用string）
    int score;     // 存储最终得分
};

// 计算单个选手的最终得分（去掉高低分后求和）
int calculateScore(int scores[]) 
{
    int sum = 0;
    int max = scores[0], min = scores[0];
    // 遍历7个分数，求和、找最大最小
    for (int i = 0; i < 7; ++i) {
        sum += scores[i];
        if (scores[i] > max) max = scores[i];
        if (scores[i] < min) min = scores[i];
    }
    return sum - max - min; // 去掉高低分后的总分
}

// 选择排序函数（按得分从高到低排序，不使用STL算法）
void sortPlayers(Player players[], int n) 
{
    for (int i = 0; i < n - 1; ++i) {
        int maxIdx = i;
        // 找到当前未排序部分的最高分下标
        for (int j = i + 1; j < n; ++j) {
            if (players[j].score > players[maxIdx].score) {
                maxIdx = j;
            }
        }
        // 交换当前元素和最高分元素，直接把姓名跟着一起交换了
        Player temp = players[i];
        players[i] = players[maxIdx];
        players[maxIdx] = temp;
    }
}

int main() {
    int n;
    cin >> n;

    // 定义原生数组存储选手信息（不使用vector）
    Player players[100]; // 假设最多100名选手，满足题目输入需求

    // 读取每个选手的信息
    for (int i = 0; i < n; ++i) 
    {
        int scores[7]; // 创建一个临时数组，用来存储7个评委分数
        cin >> players[i].name; // 读取姓名
        // 读取7个分数
        for (int j = 0; j < 7; ++j) {
            cin >> scores[j];
        }
        // 计算并存储最终得分
        players[i].score = calculateScore(scores);
    }

    // 排序选手（从高到低）
    sortPlayers(players, n);

    // 输出结果
    for (int i = 0; i < n; ++i) {
        cout << players[i].name << " " << players[i].score << endl;
    }

    return 0;
}
