using namespace std;

int main() {
    int N,w;
    cin >> N;
    w = N;
    while (N--) 
    {

        string S;
        char M;
        int n;
        cin >> S >> M >> n;
        int len = S.size();
        string res = S; // 默认无效操作时为原字符串

        if (M == 'L') {
            n %= len; // 处理n超过长度的情况
            res = S.substr(n) + S.substr(0, n);
        }
        else if (M == 'R') {
            n %= len;
            res = S.substr(len - n) + S.substr(0, len - n);
        }

        // 提取奇数位置的字符（注意：题目中位置是从1开始计数）
        string ans;
        for (int i = 0; i < res.size(); ++i) 
        {
            if (i % 2 == 0) { // 第1、3、5...位对应索引0、2、4...
                ans += res[i];
            }
        }
       if(w>1) { cout << ans << endl; }else{ cout << ans ; }
       w = w - 1;

    }
    return 0;
}
