struct Student {
    string id;       // 学号
    string name;     // 姓名
    double math;     // 数学成绩
    double chinese;  // 语文成绩
    double english;  // 英语成绩
};

int main() {
    int n;
    cin >> n;
    if (n < 1 || n > 100) {  // 班级最多100人
        return 1;
    }

    vector<Student> students(n);
    // 输入n个学生的信息
    for (int i = 0; i < n; ++i) {
        cin >> students[i].id >> students[i].name 
            >> students[i].math >> students[i].chinese >> students[i].english;
    }

    int sort_type;
    cin >> sort_type;

    // 检查排序依据是否合法
    if (sort_type != 1 && sort_type != 2 && sort_type != 3) {
        cout << "ERROR" << endl;
        return 0;
    }

    // 定义排序规则：科目降序，成绩相同则学号升序
    sort(students.begin(), students.end(), [sort_type](const Student& a, const Student& b) {
        if (sort_type == 1) {  // 数学成绩排序
            if (a.math != b.math) {
                return a.math > b.math;  // 数学降序
            }
        } else if (sort_type == 2) {  // 语文成绩排序
            if (a.chinese != b.chinese) {
                return a.chinese > b.chinese;  // 语文降序
            }
        } else {  // 英语成绩排序
            if (a.english != b.english) {
                return a.english > b.english;  // 英语降序
            }
        }
        // 成绩相同时，学号升序
        return a.id < b.id;
    });

    // 输出排序后的学号和姓名
    for (const auto& s : students) {
        cout << s.id << " " << s.name << endl;
    }

    return 0;
}
