// 冒泡排序函数：对int类型数组进行升序排序
// 参数1 sum[]：待排序的数组（本质是数组首元素的指针，会直接修改原数组）
// 参数2 size：数组中有效元素的个数（避免越界访问）
void sort(int sum[], int size) {
    for (int i = 0; i < size; i++) {
        for (int j = size - 1; j > i; j--) {
            if (sum[j] < sum[j - 1]) {
                int temp = sum[j];      
                sum[j] = sum[j - 1];    
                sum[j - 1] = temp;       
            }
        }
    }
}
int main() {
    int sum[200], m, n, size;
    cin >> m >> n;
    size = m + n;
    for (int i = 0; i < m; i++) {
        cin >> sum[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> sum[m + i];
    }
    // 调用排序函数：传数组名sum（退化为指针）和有效长度size
    sort(sum, size);
    // 去重输出相关：
    // isFirst：标记是否是第一个要输出的元素（用于控制空格，避免末尾多空格）
    bool isFirst = true;
    for (int i = 0; i < size; i++) {
        if (i == 0 || sum[i] != sum[i - 1]) {
            if (!isFirst) {cout << " ";}
            cout << sum[i];
            isFirst = false;
        }
    }
    return 0;
}
