    int matrix[10][10];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            cin >> matrix[i][j];
        }
    }
    // --- 矩形输出（蛇形行遍历） ---
    for (int i = 0; i < m; i++) {
        bool isfirst = true;
        if (i % 2 == 0) { 
            for (int j = 0; j < n; j++) {
                if (isfirst != true) { cout << " "; }
                cout << matrix[i][j];
                isfirst = false;
            }
        }
        else {  // 奇数行：从右到左
            for (int j = n - 1; j >= 0; j--) {
                if (isfirst != true) { cout << " "; }
                cout << matrix[i][j];
                isfirst = false;
            }
        }
    }
    cout << endl;
    // --- 回转输出（顺时针螺旋） ---
    int top = 0, bottom = m - 1, left = 0, right = n - 1;
    int count = 0;
    int total = m * n;
    while (count < total) {
        // 向右
        for (int j = left; j <= right && count < total; j++) {
            cout << matrix[top][j];
            count++;
            if (count < total) cout << " ";
        }
        top++;
        // 向下
        for (int i = top; i <= bottom && count < total; i++) {
            cout << matrix[i][right];
            count++;
            if (count < total) cout << " ";
        }
        right--;

        // 向左
        for (int j = right; j >= left && count < total; j--) {
            cout << matrix[bottom][j];
            count++;
            if (count < total) cout << " ";
        }
        bottom--;

        // 向上
        for (int i = bottom; i >= top && count < total; i--) {
            cout << matrix[i][left];
            count++;
            if (count < total) cout << " ";
        }
        left++;
    }
    return 0;
}
