                bool isprime = true;
                for (int j = 2; j <= sqrt(i); j++) {
                        if (i % j == 0) {isprime = false; break;}
                }
                if (isprime) { prime.push_back(i); }
        }//创建包含2到1000000的全部素数的vector容器
        int N;
        cin >> N;
        if (N <= 0 || N > 10000) { cout << "INCORRECT INPUT!"; return 0; }
        for (int z = 0; z < N; z++) 
        {
                int tem;
                cin >> tem;
                if (tem <= 0 || N > 1000000) { cout << "INCORRECT INPUT!"; return 0;}
                int MIN=-2,MAX;
                int shortlen;
                int shortprime;
                for (int i = 0;; ) {
                        if (prime[i] < tem) {
                                MIN = prime[i]; i++; continue;
                        }
                        else if (prime[i] == tem) { MAX = prime[i]; MIN = prime[i]; break;}
                        else if (prime[i] > tem) { MAX = prime[i]; break; }
                }
                 shortlen=min(MAX - tem, tem - MIN);
                if ((MAX - tem) < (tem - MIN)) { shortprime = MAX; }
                else if ((MAX - tem) > (tem - MIN)) { shortprime = MIN; }
                else if((MAX - tem) ==(tem - MIN)) { shortprime = MIN; }
                cout << shortprime << ' ' << shortlen ;
                if (z != N - 1) { cout << endl; }
        }
}
