#include <iostream>
#include <cstring> // 仅用于strlen获取字符串长度（或用指针遍历替代）
using namespace std;
int main() {
    char str1[101], str2[101];
    // 输入两个字符串（空格分隔）
    cin >> str1 >> str2;
    // 指针初始化：p1指向str1的当前起始位置，p2指向str2的当前字符
    char* p1 = str1;
    char* p2 = str2;
    // 记录匹配成功时str1的起始指针
    char* match_pos = nullptr;
    // 遍历str1的每个可能起始位置
    while (*p1 != '\0') {
        // 临时指针：p指向当前str1起始位置，q指向str2起始位置
        char* p = p1;
        char* q = str2;
        // 逐字符匹配
        while (*q != '\0' && *p == *q) {
            p++;
            q++;
        }
        // 若q遍历到str2末尾，说明匹配成功
        if (*q == '\0') {
            match_pos = p1;
            break;
        }
        // 否则，p1后移一位，尝试下一个起始位置
        p1++;
    }

    // 输出结果
    if (match_pos != nullptr) {
        // 输出str1中match_pos之前的字符（从str1起始到match_pos前）
        char* start = str1;
        while (start != match_pos) {
            cout << *start;
            start++;
        }
        cout << endl;
