#include <iostream>
using namespace std;
// 递归函数：计算走到第n阶的走法数
long long climb_stairs(int n) {
    if (n == 2) {
        return 1;
    }

    else if (n == 1) {
        return 1;
    }
    else if (n == 0) {
        return 1;
    }
    // 递推公式：f(n) = f(n-2) + f(n-3)
    return climb_stairs(n - 2) + climb_stairs(n - 3);
}

int main() {
