//有点懒
汉诺塔
【例5.23】古印度的著名智力测验问题：有三个立柱A、B、C，在A柱上穿有大小不等的圆盘64个，较大的圆盘在下，较小者在上。要求借助于B柱将A柱上的64个圆盘移到C柱，规则为：
(1) 每次只能把一个柱上最上面的圆盘移至另一个柱的最上面;
(2) 每个柱上总保持较大的圆盘在下，较小者在上。
编制程序, 实现将任意n个圆盘从A柱借助于B柱移到C柱, 并显示出全部移动过程
#include<iostream>              
using namespace std;               
void move(char source, char target)  //  定义无返回值函数move，接收两个char参数：源柱、目标柱
{
        cout << source << "=>" << target << endl; //  输出移动步骤（比如"A=>C"，表示盘子从A移到C）
}

void hanoi(int n, char source, char temp, char target) { 
        // n=n的核心含义是 “当前递归层需要处理的盘子数量”
        // —— 更具体地说，是 “需要从source柱移动到target柱的盘子总数
        // source=源柱，temp=中转柱，target=目标柱
        // 注意这些都是形参，并不是说这三根柱子固定
        //hanoi函数的作用就是把n个盘子借助第二个参数的柱子从第一个参数的柱子移动到第三个参数的柱子
        if (n == 1)                                          //递归终止条件：只有1个盘子时
                move(source, target);                          // 直接调用move，把这个盘子从源柱移到目标柱
        else {                                             //  递归条件：盘子数>1时
                // 将n-1个盘子从一柱，以三柱为中转，移到二柱
                hanoi(n - 1, source, target, temp);                
                //  关键1：拆解子问题1——先挪走上面n-1个盘子到二柱
                // 将最下面的第n个盘子从一柱直接移到三柱
                move(source, target);                         // 8. 关键2：移动最底层的大盘子到目标柱
                // 将n-1个盘子从中转柱，以源柱为中转，移到目标柱
                hanoi(n - 1, temp, source, target);               
                // 9. 关键3：拆解子问题2——把n-1个盘子从中转柱挪到目标柱
        }
}


int main() {                       
        int n;                       
        cout << "输入盘子数：" << endl;     
        cin >> n;                         
        hanoi(n, 'A', 'B', 'C');          
        return 0;                       
}
