#include <iostream>
#include <vector>
#include <string>

using namespace std;

int main() {
    int size, n;
    // 读取内存大小
    if (!(cin >> size)) return 0;
    // 读取操作次数
    if (!(cin >> n)) return 0;

    // 初始化内存，0 表示空闲，1 表示已分配
    vector<int> memory(size, 0);

    for (int i = 0; i < n; ++i) {
        string op;
        cin >> op;

        if (op == "ALLOCATE") {
            int request_size;
            cin >> request_size;

            int found_idx = -1;
            // 遍历内存寻找第一个足够大的连续空闲块
            for (int j = 0; j <= size - request_size; ++j) {
                bool can_allocate = true;
                for (int k = j; k < j + request_size; ++k) {
                    if (memory[k] == 1) {
                        can_allocate = false;
                        break;
                    }
                }
                if (can_allocate) {
                    found_idx = j;
                    break;
                }
            }

            if (found_idx != -1) {
                // 标记为已分配
                for (int j = found_idx; j < found_idx + request_size; ++j) {
                    memory[j] = 1;
                }
                cout << "Allocate at index " << found_idx << endl;
            }
            else {
                cout << "Allocation failed" << endl;
            }

        }
        else if (op == "FREE") {
            int start, length;
            cin >> start >> length;

            bool is_valid = true;
            // 1. 检查越界 (索引小于0或超出数组范围)
            if (start < 0 || length <= 0 || start + length > size) {
                is_valid = false;
            }
            else {
                // 2. 检查释放的内存块是否包含未分配（已经是0）的部分
                for (int j = start; j < start + length; ++j) {
                    if (memory[j] == 0) {
                        is_valid = false;
                        break;
                    }
                }
            }

            if (is_valid) {
                // 执行释放，置为0
                for (int j = start; j < start + length; ++j) {
                    memory[j] = 0;
                }
                cout << "Free " << length << " blocks from index " << start << endl;
            }
            else {
                cout << "Invalid free operation" << endl;
            }
        }
    }

    return 0;
}
