#include <iostream>
#include <cstring>
using namespace std;
// 重载函数1：八进制字符串转十进制整数（按权展开法）
int radixConvert(char octString[], int len) {
    int decimal = 0;
    for (int i = 0; i < len; i++) {
        int digit = octString[i] - '0'; // 字符转数字
        int weight = 1;//计算权重
        for (int j = 0; j < len - 1 - i; j++) {
            weight *= 8;
        }
        decimal += digit * weight;
    }
    return decimal;
}
// 重载函数2：十进制整数转八进制字符串（取余法）
void radixConvert(int n) {
    char oct[7] = { 0 };
    int index = 0;
    if (n == 0) { 
        cout << "0";
        return;
    }
    // 取余法：除8取余，逆序存储
    while (n > 0) {
        int remainder = n % 8;
        oct[index++] = remainder + '0'; // 数字转字符
        n = n / 8;
    }
    // 逆序输出（因为取余结果是倒序的）
