int main() {
    int M;
    cin >> M;
    if (M <= 0 || M >= 6) { // 题目要求0<M<6
        cout << "Wrong input" << endl;
        return 0;
    }
    for (int i = 0; i < M; i++) {
        char c;
        char data[7]; // 八进制最长6位，十进制最长65535（5位）
        cin >> c >> data;

        if (c == 'O' || c == 'o') {
            // 八进制字符串转十进制
            int len = strlen(data);
            if (len > 6) { // 题目限制八进制字符串最长6位
                cout << "Wrong input" << endl;
                return 0;
            }
            // 验证八进制字符是否合法（只能是0-7）
            for (int j = 0; j < len; j++) {
                if (data[j] < '0' || data[j] > '7') {
                    cout << "Wrong input" << endl;
                    return 0;
                }
            }
            int decimal = radixConvert(data, len);
            cout << decimal << endl;
        }
        else if (c == 'D' || c == 'd') {
            // 十进制数字转八进制
            int num = atoi(data); // 字符串转整数
            if (num < 0 || num > 65535) { // 题目限制非负且不超过65535
                cout << "Wrong input" << endl;
                return 0;
            }
            radixConvert(num);
            cout << endl;
        }
        else {
            // 其他字符，输入错误
            cout << "Wrong input" << endl;
            return 0;
        }
    }

    return 0;
}
