// 重载函数1：八进制字符串转十进制整数（按权展开法）
int radixConvert(char test[], int len) {
        int res=0;
        for (int i = 0; i<len; i++) {
                int num = 0;
                num = test[i] - '0';
                int weight=1;
                for (int j = 1; j <= len - i - 1; j++) { weight*=8; }
                res += num * weight;     
        }
        cout << res << endl;
        return 0;
}
void radixConvert(int n) {
        char test[8] = { 0 };
        int count = 0;
        while (n > 0) {        
                test[count++] = n % 8+'0';
                n /= 8;
        }
        for (int i = count - 1; i >=0; i--) {
                cout << test[i];        
        }
        cout << endl;
}

