#include <iostream>
using namespace std;

class MyStrArr
{
private:
    char **strArr;   // 字符指针数组
    int count;       // 字符串个数

public:
    // 构造函数
    MyStrArr(char **arr, int n)
    {
        count = n;
        strArr = new char*[count];
        for(int i = 0; i < count; i++)
        {
            strArr[i] = arr[i];
        }
    }

    // 数据处理函数
    void Fun()
    {
        for(int i = 0; i < count; i++)
        {
            char temp[105];     // 临时数组存放保留字符
            int k = 0;

            // 遍历当前字符串
            for(int j = 0; strArr[i][j] != '\0'; j++)
            {
                // 条件：下标为偶数 且 ASCII 为偶数
                if(j % 2 == 0 && ((int)strArr[i][j]) % 2 == 0)
                {
                    temp[k++] = strArr[i][j];
                }
            }

            temp[k] = '\0';

            // 排序，冒泡排序
            for(int m = 0; m < k - 1; m++)
            {
                for(int n = 0; n < k - 1 - m; n++)
                {
                    if(temp[n] > temp[n+1])
                    {
                        char t = temp[n];
                        temp[n] = temp[n+1];
                        temp[n+1] = t;
                    }
                }
            }

            // 复制回原字符串
            int idx = 0;
            while(temp[idx] != '\0')
            {
                strArr[i][idx] = temp[idx];
                idx++;
            }
            strArr[i][idx] = '\0';
        }
    }

    // 输出函数
    void Output()
    {
        for(int i = 0; i < count; i++)
        {
            if(strArr[i][0] == '\0')
                cout << 0 << endl;
            else
                cout << strArr[i] << endl;
        }
    }
};

int main()
{
    int len;
    cin >> len;

    char **arr = new char*[len];

    for(int i = 0; i < len; i++)
    {
        arr[i] = new char[105];
        cin >> arr[i];
    }

    MyStrArr obj(arr, len);

    obj.Fun();
    obj.Output();

    return 0;
}
