#include<iostream>
using namespace std;
struct node {
        int val;
        node* next;
        node(int a) :next(NULL), val(a) {        }
};
class list {
private:
        node* head;
        node* tail;
        int count;
public:
        list():head(NULL),tail(NULL),count(0){}
        void insert(int k,int val){
                if (k<1 || k>count + 1) {
                        return;
                }
                if (k > 1 && head == NULL) {
                        return;
                }
                node* newnode = new node(val);
                if (k == 1) {
                        newnode->next = head;
                        head = newnode;
                        if (head == NULL) {
                                tail = newnode;
                        }
                        count++;
                        return;
            }
                if (k == count + 1) {
                        tail->next = newnode;
                        tail = newnode;
                        count++;
                        return;
                }
                if (k > 1 && k < count + 1) {
                        node* curr = head;
                        int pos = 1;
                        for (pos; pos < k - 1; pos++) {
                                curr = curr->next;
                        }
                        newnode->next=curr->next;
                        curr->next = newnode;//剪断
                        count++;
                }

        }
        int find(int val){
                node* curr = head;
                int pos = 1;
                bool iffind=false;
                for (int i = 0; i < count; i++) {
                        if (curr->val == val) {
                                iffind = true;
                                break;
                        }
                        pos++;
                        curr = curr->next;
                }if (iffind) { return pos; }
                else { return -1; }
        }
        void deleted(int val){
                node* curr = head;
                if (curr->val == val) {
                        node* tem = head;
                        head = curr->next;
                        curr = curr->next;                
                        delete tem;
                        count--;
                }//只要curr指向的不是最后一个节点
                while (curr->next != NULL) {
                        if (curr->next->val == val) {
                                node* tem = curr->next;
                                curr->next = curr->next->next;
                                delete tem;
                                count--;
                        }
                        curr = curr->next;
                }
        }
};
int main() {
        list mylist;
        int rule;
        cin >> rule;
        while (rule != 4) {
                if (rule == 1) {
                        int x, y;
                        cin >> x >> y;
                        mylist.insert(x, y);
                }
                else if (rule == 2) {
                        int x;
                        cin >> x;
                        cout<<mylist.find(x)<<endl;
                }
                else if (rule == 3) {
                        int x;
                        cin >> x;
                        mylist.deleted(x);
                }
                cin >> rule;
        }
}
