#include <bits/stdc++.h>
using namespace std;

template <class T>
struct Node {
    T data;
    Node<T>* next;

    Node(const T& d = T(), Node<T>* n = nullptr) : data(d), next(n) {}
};

template <class T>
class List {
protected:
    Node<T>* head;
    int len;

public:
    List() : head(nullptr), len(0) {}

    virtual ~List() {
        clear();
    }

    void clear() {
        while (head) {
            Node<T>* p = head;
            head = head->next;
            delete p;
        }
        len = 0;
    }

    virtual void Insert(const T& x) {
        Node<T>* node = new Node<T>(x);

        if (!head || x < head->data) {
            node->next = head;
            head = node;
        } else {
            Node<T>* p = head;
            while (p->next && p->next->data <= x) {
                p = p->next;
            }
            node->next = p->next;
            p->next = node;
        }

        len++;
    }

    virtual void Remove(const T& x) {
        while (head && head->data == x) {
            Node<T>* p = head;
            head = head->next;
            delete p;
            len--;
        }

        Node<T>* cur = head;
        while (cur && cur->next) {
            if (cur->next->data == x) {
                Node<T>* p = cur->next;
                cur->next = p->next;
                delete p;
                len--;
            } else {
                cur = cur->next;
            }
        }
    }

    T& operator[](int index) {
        Node<T>* p = head;
        for (int i = 0; i < index; i++) {
            p = p->next;
        }
        return p->data;
    }

    friend ostream& operator<<(ostream& os, const List<T>& list) {
        Node<T>* p = list.head;
        while (p) {
            os << p->data;
            if (p->next) os << ' ';
            p = p->next;
        }
        return os;
    }
};

template <class T>
class Stack : public List<T> {
public:
    void Insert(const T& x) override {
        Node<T>* node = new Node<T>(x, this->head);
        this->head = node;
        this->len++;
    }

    void Remove(const T& x) override {
        (void)x;
        if (!this->head) return;

        Node<T>* p = this->head;
        this->head = this->head->next;
        delete p;
        this->len--;
    }
};

template <class T>
class Queue : public List<T> {
public:
    void Insert(const T& x) override {
        Node<T>* node = new Node<T>(x);

        if (!this->head) {
            this->head = node;
        } else {
            Node<T>* p = this->head;
            while (p->next) p = p->next;
            p->next = node;
        }

        this->len++;
    }

    void Remove(const T& x) override {
        (void)x;
        if (!this->head) return;

        Node<T>* p = this->head;
        this->head = this->head->next;
        delete p;
        this->len--;
    }
};

template <class T>
void solve(char kind) {
