#include<iostream>
using namespace std;
struct node {
        int val;
        node* next;
        node(int a) :val(a), next(NULL) {}
};
class list {
public:
        node* head;
        node* tail;
        int count;
        list() :head(NULL), tail(NULL), count(0) {}
        friend ostream& operator<<(ostream& cout, const list& l);
        friend istream& operator>>(istream& cin, list& l);
        void pushback(int val) {
                node* newnode = new node(val);
                if (tail == NULL) {
                        tail = newnode;
                        head = newnode;
                        count++;
                        return;
                }
                tail->next = newnode;
                tail = newnode;
                count++;
                return;
        }
        void rearrange() {
                list l1;
                list l2;
                int index = 0;
                node* curr = head;
                while (curr != NULL) {
                        index++;
                        if (index % 2 == 1 && curr->val % 2 == 1) {
                                l1.pushback(curr->val);
                        }
                        else if (index % 2 == 0 && curr->val % 2 == 0) {
                                l2.pushback(curr->val);
                        }
                        curr = curr->next;
                }
                if (l1.head == NULL) {
                        cout << l2;
                        return;
                }
                if (l2.head != NULL) {
                        l1.tail->next = l2.head;
                }
                cout << l1;
                return;
        }
};
ostream& operator<<(ostream& cout, const list& l) {
        node* curr = l.head;
        if (curr == NULL) {
                cout << "NULL";
        }
        while (curr != NULL) {
                cout << curr->val << ' ';
                curr = curr->next;
        }
        return cout;
}
