#include <iostream>
using namespace std;

template<class T>
class MyContainer {
private:
    T* data;
    int len;

public:
    MyContainer(T array[], int n) {
        len = n;
        data = new T[len];
        for (int i = 0; i < len; i++) {
            data[i] = array[i];
        }
    }

    ~MyContainer() {
        delete[] data;
    }

    void add(const T& value) {
        T* newData = new T[len + 1];

        for (int i = 0; i < len; i++) {
            newData[i] = data[i];
        }

        newData[len] = value;

        delete[] data;
        data = newData;
        len++;
    }

    bool remove(int idx) {
        if (idx < 0 || idx >= len) {
            return false;
        }

        T* newData = new T[len - 1];

        for (int i = 0; i < idx; i++) {
            newData[i] = data[i];
        }

        for (int i = idx + 1; i < len; i++) {
            newData[i - 1] = data[i];
        }

        delete[] data;
        data = newData;
        len--;

        return true;
    }

    bool empty() {
        return len == 0;
    }

    int size() {
        return len;
    }

    void display() {
        if (empty()) {
            cout << "None" << endl;
            return;
        }

        cout << "[";
        for (int i = 0; i < len; i++) {
            cout << data[i];
            if (i != len - 1) {
                cout << ",";
            }
        }
        cout << "]" << endl;
    }

    void clear() {
        delete[] data;
        data = nullptr;
        len = 0;
    }
};

