#include <iostream>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;

    ListNode(int v = 0) : val(v), next(nullptr) {}
};

class LinkedList {
private:
    ListNode* head;

public:
    LinkedList() : head(nullptr) {}

    ListNode* getHead() const {
        return head;
    }

    void pushBack(int val) {
        ListNode* node = new ListNode(val);

        if (head == nullptr) {
            head = node;
            return;
        }

        ListNode* cur = head;
        while (cur->next != nullptr) {
            cur = cur->next;
        }
        cur->next = node;
    }

    static ListNode* reverse(ListNode* head) {
        ListNode* prev = nullptr;
        ListNode* cur = head;

        while (cur != nullptr) {
            ListNode* nextNode = cur->next;
            cur->next = prev;
            prev = cur;
            cur = nextNode;
        }

        return prev;
    }

    static void print(ListNode* head) {
        ListNode* cur = head;
        while (cur != nullptr) {
            cout << cur->val;
            if (cur->next != nullptr) cout << " ";
            cur = cur->next;
        }
        cout << endl;
    }

    ListNode* operator+(LinkedList& other) {
        ListNode* p = reverse(this->head);
        ListNode* q = reverse(other.head);

        ListNode dummy;
        ListNode* tail = &dummy;

        int carry = 0;//进位

        while (p != nullptr || q != nullptr || carry != 0) {
            int sum = carry;

            if (p != nullptr) {
                sum += p->val;
                p = p->next;
            }

            if (q != nullptr) {
                sum += q->val;
                q = q->next;
            }

            carry = sum / 10;
            tail->next = new ListNode(sum % 10);
            tail = tail->next;
        }

        return dummy.next;
    }
};

int main() {
    int a, b;
    cin >> a >> b;

    LinkedList A, B;

    for (int i = 0; i < a; i++) {
        int x;
        cin >> x;
        A.pushBack(x);
    }

    for (int i = 0; i < b; i++) {
        int x;
        cin >> x;
        B.pushBack(x);
    }

    ListNode* result = A + B;
    LinkedList::print(result);

    return 0;
}
