#include <iostream>
using namespace std;

const int MAXLEN = 20;

template<class T>
class MyStack {
private:
    T data[MAXLEN];
    int topIndex;

public:
    MyStack(T array[], int len) {
        topIndex = -1;

        for (int i = 0; i < len && i < MAXLEN; i++) {
            data[++topIndex] = array[i];
        }
    }

    void push(const T& value) {
        if (topIndex == MAXLEN - 1) {
            cout << "FULL" << endl;
            return;
        }

        data[++topIndex] = value;
    }

    T pop() {
        if (empty()) {
            cout << "None" << endl;
            return T();
        }

        return data[topIndex--];
    }

    bool empty() {
        return topIndex == -1;
    }

    int count() {
        return topIndex + 1;
    }

    void show() {
        if (empty()) {
            cout << "None" << endl;
            return;
        }

        for (int i = 0; i <= topIndex; i++) {
            cout << data[i] << " ";
        }

        cout << count() << endl;
    }

    void clear() {
        topIndex = -1;
    }
};

template<class T>
void solve(MyStack<T>& stack) {
    char op;

    while (cin >> op) {
        if (op == 's') {
            break;
        } else if (op == 'd') {
            stack.show();
