#include <iostream>
using namespace std;

template<class T>
class list {
private:
    struct node {
        T data;
        node* next;
    };

    node* head;
    node* tail;

public:
    list() {
        head = nullptr;
        tail = nullptr;
    }

    void Insert(T item) {
        node* p = new node;
        p->data = item;
        p->next = head;

        head = p;

        if (tail == nullptr) {
            tail = p;
        }
    }

    void Append(T item) {
        node* p = new node;
        p->data = item;
        p->next = nullptr;

        if (head == nullptr) {
            head = tail = p;
        } else {
            tail->next = p;
            tail = p;
        }
    }

    int count() {
        int cnt = 0;
        node* p = head;

        while (p != nullptr) {
            cnt++;
            p = p->next;
        }

        return cnt;
    }

    void htot() {
        if (head == nullptr || head == tail) {
            return;
        }

        node* oldHead = head;
        head = head->next;

        oldHead->next = nullptr;
        tail->next = oldHead;
        tail = oldHead;
    }

    void ttoh() {
        if (head == nullptr || head == tail) {
            return;
        }

        node* prev = nullptr;
        node* cur = head;

        while (cur->next != nullptr) {
            prev = cur;
            cur = cur->next;
        }

        prev->next = nullptr;
        tail = prev;

        cur->next = head;
        head = cur;
    }

    void display() {
        if (head == nullptr) {
            cout << "emptylist" << endl;
            return;
        }

        node* p = head;
        while (p != nullptr) {
            cout << p->data;
            if (p->next != nullptr) {
                cout << " ";
            }
            p = p->next;
        }
        cout << endl;
    }

    void SortList() {
        int n = count();
        if (n == 0) {
            cout << "emptylist" << endl;
            return;
        }

        T* arr = new T[n];

        node* p = head;
        for (int i = 0; i < n; i++) {
            arr[i] = p->data;
            p = p->next;
        }

        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - 1 - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    T temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            cout << arr[i];
            if (i != n - 1) {
                cout << " ";
            }
        }
        cout << endl;

        delete[] arr;
    }
};

int main() {
    string type;
    int n;

    cin >> type;
    cin >> n;

    if (type == "int") {
        list<int> link1;
        list<int> link2;

        for (int i = 0; i < n; i++) {
