#include <iostream>
using namespace std;

class Complex {
private:
    int real;
    int imag;

public:
    Complex(int r = 0, int i = 0) {
        real = r;
        imag = i;
    }

    Complex operator-(const Complex& other) {
        return Complex(real - other.real, imag - other.imag);
    }

    Complex operator+(const Complex& other) {
        return Complex(real + other.real, imag + other.imag);
    }

    Complex operator*(const Complex& other) {
        int r = real * other.real - imag * other.imag;
        int i = real * other.imag + imag * other.real;
        return Complex(r, i);
    }

    void print() {
        if (real == 0 && imag == 0) {
            cout << 0 << endl;
        } else if (imag == 0) {
            cout << real << endl;
        } else if (real == 0) {
            if (imag == 1) {
                cout << "i" << endl;
            } else if (imag == -1) {
                cout << "-i" << endl;
            } else {
                cout << imag << "i" << endl;
            }
        } else {
            cout << real;

            if (imag > 0) {
                cout << "+";
            }

            if (imag == 1) {
                cout << "i";
            } else if (imag == -1) {
                cout << "-i";
            } else {
                cout << imag << "i";
            }

            cout << endl;
        }
    }
};

int main() {
