            cout << "No" << endl;
            continue;
        }
        bool found = false;
        for (int i = 2; i <= len - 2; i++) {
            string left = s.substr(0, i);
            string right = s.substr(i);
            if (isPalindrome(left) && isPalindrome(right)) {
                found = true;
                break;
            }
        }
        if(found)
        {
                judge.push_back("Yes");
                }
