# include<iostream>
using namespace std;

class Date {
private:
    int year;
    int month;
    int day;

    // 判断是否为闰年
    bool isLeapYear(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    // 获取指定月份的天数
    int getDaysInMonth(int y, int m) {
        int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        // 闰年2月29天
        if (m == 2 && isLeapYear(y)) return 29;
        return days[m];
    }

public:
    // 初始化日期
    Date(int y, int m, int d) : year(y), month(m), day(d) {}

    // 显示日期函数
    void display() {
        cout << year << "-" << month << "-" << day << endl;
    }

    // 加天数函数
    Date addDays(int days) {
        Date res = *this;
        res.day += days;
        while (res.day > getDaysInMonth(res.year, res.month)) {
            res.day -= getDaysInMonth(res.year, res.month);
            res.month++;
            if (res.month > 12) {
                res.month = 1;
                res.year++;
            }
        }
        return res;
    }

    // 减天数函数
    Date subDays(int days) {
        Date res = *this;
        res.day -= days;
        while (res.day <= 0) {
            res.month--;
            if (res.month < 1) {
                res.month = 12;
                res.year--;
            }
            res.day += getDaysInMonth(res.year, res.month);
        }
        return res;
    }
};

int main() {
    int y, m, d;
    int sub_val, add_val;

    // 输入：年 月 日 减少天数 增加天数
    cin >> y >> m >> d >> sub_val >> add_val;

    // 创建日期对象
    Date dt(y, m, d);

    // 输出当前日期
    dt.display();

    // 输出减少天数后的日期
    Date dtSub = dt.subDays(sub_val);
    dtSub.display();

    // 输出增加天数后的日期
    Date dtAdd = dt.addDays(add_val);
    dtAdd.display();

    return 0;
}
