#include <iomanip>
using namespace std;
class CStudent {
private:
    string name;
    string id;
    int math;
    int english;

    // 静态数据成员
    static int count;           // 学生总人数
    static int mathTotal;       // 数学总成绩
    static int englishTotal;    // 英语总成绩

public:
    // 构造函数
    CStudent(string n, string i, int m, int e) : name(n), id(i), math(m), english(e) {
        count++;
        mathTotal += m;
        englishTotal += e;
    }

    // 拷贝构造函数
    CStudent(const CStudent& other) : name(other.name), id(other.id), 
                                       math(other.math), english(other.english) {
        count++;
        mathTotal += math;
        englishTotal += english;
        // cout << "拷贝构造函数被调用" << endl;  
    }

    // 赋值运算符
    CStudent& operator=(const CStudent& other) {
        if (this != &other) {
            // 先减去当前对象的数据
            count--;
            mathTotal -= math;
            englishTotal -= english;

            // 拷贝数据
            name = other.name;
            id = other.id;
            math = other.math;
            english = other.english;

            // 加上新对象的数据
            count++;
            mathTotal += math;
            englishTotal += english;
        }
        return *this;
    }

    // 析构函数
    ~CStudent() {
        count--;
        mathTotal -= math;
        englishTotal -= english;
    }

    // 设置数学成绩
    void setMath(int m) {
        mathTotal -= math;  // 减去旧成绩
        math = m;
        mathTotal += math;  // 加上新成绩
    }

    // 设置英语成绩
    void setEnglish(int e) {
        englishTotal -= english;  // 减去旧成绩
        english = e;
        englishTotal += english;  // 加上新成绩
    }

    // 求本人总成绩
    int getTotalScore() const {
        return math + english;
    }

    // 获取姓名
    string getName() const {
        return name;
    }

    // 获取学号
    string getId() const {
        return id;
    }

    // 获取数学成绩
    int getMath() const {
        return math;
    }

    // 获取英语成绩
    int getEnglish() const {
        return english;
    }

    // 输出数据
    void display() const {
        cout << name << " " << id << " " << math << " " << english << " " << getTotalScore() << endl;
    }

    // 输出数学平均分
    static void outputMathAverage() {
        if (count == 0) {
            cout << "0.0" << endl;
            return;
        }
        double avg = (double)(mathTotal) / count;
        cout << fixed << setprecision(1) << avg << endl;
    }

    // 输出英语平均分
    static void outputEnglishAverage() {
        if (count == 0) {
            cout << "0.0" << endl;
            return;
        }
        double avg = static_cast<double>(englishTotal) / count;
        cout << fixed << setprecision(1) << avg << endl;
    }
};

// 冒泡排序
void bubbleSort(vector<CStudent>& students) {
    int n = students.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (students[j].getTotalScore() < students[j + 1].getTotalScore()) {
                swap(students[j], students[j + 1]); 
            }
        }
    }
}

// 初始化静态数据成员
int CStudent::count = 0;
int CStudent::mathTotal = 0;
int CStudent::englishTotal = 0;

// 比较函数
bool compareStudents(const CStudent& a, const CStudent& b) {
    return a.getTotalScore() > b.getTotalScore();
}

int main() {
    vector<CStudent> students;
    string name, id;
    int math, english;

    // 输入10名学生的数据
    for (int i = 0; i < 10; i++) {
        cin >> name >> id >> math >> english;
        // 创建对象 构造函数更新静态数据
        students.emplace_back(name, id, math, english);
    }

    // 输出数学平均分
    CStudent::outputMathAverage();

    // 输出英语平均分
    CStudent::outputEnglishAverage();

    // 直接对对象进行排序
    bubbleSort(students);

    // 输出前三名学生信息
    for (int i = 0; i < 3; i++) {
        students[i].display();
    }

    return 0;
}
