#include <iostream>
#include <string>
#include <stack>
#include <iomanip>

using namespace std;

class Calculator {
private:
    string expression;
    stack<double> numStack;    // 操作数栈
    stack<char> opStack;       // 运算符栈

    // 判断字符是否为数字
    bool isDigit(char c) {
        return (c >= '0' && c <= '9');
    }

    // 判断运算符优先级
    int precedence(char op) {
        if (op == '+' || op == '-') return 1;
        if (op == '*' || op == '/') return 2;
        return 0;
    }

    // 执行运算
    double applyOp(double a, double b, char op) {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '*': return a * b;
            case '/': return a / b;
            default: return 0;
        }
    }

    // 将字符串转换为数字
    double stringToDouble(const string& str) {
        double result = 0.0; // 整数部分
        double decimal = 0.0; // 小数部分
        int decimalCount = 0; // 小数位数
        bool isNegative = false; // 是否是负数
        bool isDecimal = false; // 是否是小数部分
        int start = 0;

        // 处理负号
        if (str[0] == '-') {
            isNegative = true;
            start = 1;
        }

        for (int i = start; i < str.length(); i++) {
            char c = str[i];
            if (c == '.') {
                isDecimal = true;
                decimalCount = 0;
                continue;
            }

            int digit = c - '0';  // 字符转数字

            if (!isDecimal) { // 整数部分
                result = result * 10 + digit;
            } else { // 小数部分
                decimalCount++;
                decimal = decimal * 10 + digit;
            }
        }

        // 处理小数部分
        if (decimalCount > 0) {
            double decimalDivisor = 1.0;
            for (int i = 0; i < decimalCount; i++) {
                decimalDivisor *= 10.0;
            }
            result = result + decimal / decimalDivisor;
        }

        return isNegative ? -result : result;
    }


    // 处理运算符
    void processOperator(char op) {
        while (!opStack.empty() && precedence(opStack.top()) >= precedence(op)) {
            char topOp = opStack.top();
            opStack.pop();

            double b = numStack.top(); numStack.pop();
            double a = numStack.top(); numStack.pop();

            // 检查除数是否为0
            if (topOp == '/' && b == 0) {
                throw "WRONG";
            }

            double result = applyOp(a, b, topOp);
            numStack.push(result);
        }
        opStack.push(op);
    }


public:
    Calculator() {}

    double calculate(const string& expr) {
        expression = expr;

        // 清除之前的栈
        while (!numStack.empty()) numStack.pop();
        while (!opStack.empty()) opStack.pop();


            size_t i = 0;
            while (i < expression.length()) {
                char c = expression[i];

                // 处理数字
                if (isDigit(c) || (c == '-' && (i == 0 || !isDigit(expression[i-1])))) { // 是数字
                    // 负号
                    if (c == '-') {
                        i++; 
                    }

                    // 解析数字
                    string numStr;
                    if (c == '-') {
                        numStr += '-';
                        c = expression[i];
                    }

                    while (i < expression.length() && (isDigit(expression[i]) || expression[i] == '.')) {
                        numStr += expression[i];
                        i++;
                    }

                    double num = stringToDouble(numStr);
                    numStack.push(num);
                    continue;
                }

                // 处理运算符
                if (c == '+' || c == '-' || c == '*' || c == '/') {
                    processOperator(c);
                    i++;
                }
                else {
                    i++;  // 跳过其他字符
                }
            }

            // 计算剩余符号
            while (!opStack.empty()) {
                char op = opStack.top();
                opStack.pop();

                double b = numStack.top(); numStack.pop();
                double a = numStack.top(); numStack.pop();

                // 检查除数是否为0
                if (op == '/' && b == 0) {
                    throw "WRONG";
                }

                double result = applyOp(a, b, op);
                numStack.push(result);
            }

            // 返回结果
            if (numStack.size() == 1) {
                double result = numStack.top();
                return result;
            }
            else {
                throw "WRONG";
            }
    }
};

int main() {
    string expression;
    cin >> expression;

    Calculator calc;
    double result = calc.calculate(expression);

    cout << setprecision(2) << result;

    return 0;
}
