翻转后栈序列：1 2 3 5 4 3 2 1
pop两次后栈序列：1 2 3 5 4 3
#include <iostream>
using namespace std;
#define MAX_SIZE 15
class myStack{
    double data[MAX_SIZE];
    int top;//栈顶下标
public:
    myStack(); //构造函数
    bool isEmpty(); //栈空判断
    bool isFull(); //栈满判断
    int length(); //返回栈中数据数量
    bool push(double a); //进栈
    double pop(); //出栈
    void operator ~(); //运算符重载，倒序翻转栈数据
    void printData(); //从0到top打印栈序列，空栈打印"Empty stack"
};

// 构造函数：初始化栈，top指向-1表示空栈
myStack::myStack() {
    top = -1;
}

// 判断栈是否为空
bool myStack::isEmpty() {
    return top == -1;
}

// 判断栈是否已满
bool myStack::isFull() {
    return top == MAX_SIZE - 1;
}

// 返回栈中数据数量
int myStack::length() {
    return top + 1;
}

// 进栈操作
bool myStack::push(double a) {
    if (isFull()) {
        return false;  // 栈满，进栈失败
    }
    data[++top] = a;
    return true;
}

// 出栈操作
double myStack::pop() {
    if (isEmpty()) {
        return -1;  // 栈空，返回-1
    }
    return data[top--];
}

// 运算符重载：倒序翻转栈数据
void myStack::operator~() {
    if (isEmpty() || length() == 1) {
        return;  // 空栈或只有一个元素，不需要翻转
    }

    int left = 0;
    int right = top;

    while (left < right) {
        // 交换左右两端的元素
        double temp = data[left];
        data[left] = data[right];
        data[right] = temp;
        left++;
        right--;
    }
}

// 打印栈数据（从栈底到栈顶）
void myStack::printData() {
    if (isEmpty()) {
        cout << "Empty stack" << endl;
        return;
    }

    for (int i = 0; i <= top; i++) {
        cout << data[i] << " ";
    }
    cout << endl;
}

int main(){
    myStack stack;
    double num;

    // 读取输入直到遇到0
    while (cin >> num && num != 0) {
        if (!stack.push(num)) {
            cout << "Stack is full!" << endl;
            break;
        }
    }

    // 打印原始栈序列
    cout << "原始栈序列：";
    stack.printData();

    // 倒序翻转
    ~stack;

    // 打印翻转后的栈序列
    cout << "翻转后栈序列：";
    stack.printData();

    // 打印pop后到栈序列
    stack.pop();
    stack.pop();
    cout<< "pop两次后栈序列：";
    stack.printData();

    return 0;

}
#include <iostream>
using namespace std;

class MyStrArr
{
private:
    char **strArr;   // 字符指针数组
    int count;       // 字符串个数

public:
    // 构造函数
    MyStrArr(char **arr, int n)
    {
        count = n;
        strArr = new char*[count];
        for(int i = 0; i < count; i++)
        {
            strArr[i] = arr[i];
        }
    }

    // 数据处理函数
    void Fun()
    {
        for(int i = 0; i < count; i++)
        {
            char temp[105];     // 临时数组存放保留字符
            int k = 0;

            // 遍历当前字符串
            for(int j = 0; strArr[i][j] != '\0'; j++)
            {
                // 条件：下标为偶数 且 ASCII 为偶数
                if(j % 2 == 0 && ((int)strArr[i][j]) % 2 == 0)
                {
                    temp[k++] = strArr[i][j];
                }
            }

            temp[k] = '\0';

            // 排序，冒泡排序
            for(int m = 0; m < k - 1; m++)
            {
                for(int n = 0; n < k - 1 - m; n++)
                {
                    if(temp[n] > temp[n+1])
                    {
                        char t = temp[n];
                        temp[n] = temp[n+1];
                        temp[n+1] = t;
                    }
                }
            }

            // 复制回原字符串
            int idx = 0;
            while(temp[idx] != '\0')
            {
                strArr[i][idx] = temp[idx];
                idx++;
            }
            strArr[i][idx] = '\0';
        }
    }

    // 输出函数
    void Output()
    {
        for(int i = 0; i < count; i++)
        {
            if(strArr[i][0] == '\0')
                cout << 0 << endl;
            else
                cout << strArr[i] << endl;
        }
    }
};

int main()
{
    int len;
    cin >> len;

    char **arr = new char*[len];

    for(int i = 0; i < len; i++)
    {
        arr[i] = new char[105];
        cin >> arr[i];
    }

    MyStrArr obj(arr, len);

    obj.Fun();
    obj.Output();

    return 0;
}
