#include <iostream>
using namespace std;
const int max_size = 10;
class queue
{
private:
    float data[max_size];
    int front, rear;//头，尾
    int num;

public:
    // 构造函数
    queue(void)
    {
        front = rear = -1;
        num = 0;
    }

    // 判断是否为空
    bool Empty(void)
    {
        return num == 0;
    }

    // 判断是否已满
    bool Full(void)
    {
        return num == max_size;
    }

    // 入队
    void Add(float x)
    {
        if(!Full())
        {
            rear++;
            data[rear] = x;
            num++;
        }
    }

    // 出队
    float Delete(void)
    {
        if(!Empty())
        {
            front++;
            num--;
            return data[front];
        }
        return -1;  // 感觉Add和Full这两个条件 题目的描述有问题，常规队列满时，需要进行数据的迁移，否则应写成循环队列（取模的形式）或者链表的形式
    }
};

int main()
{
    int n;
    cin >> n;

    queue q;

    for(int i = 0; i < n; i++)
    {
        int op;
        cin >> op;

        if(op == 0)   // 入队
        {
            float x;
            cin >> x;
            q.Add(x);
        }
        else if(op == 1)   // 出队
        {
            if(!q.Empty())
                cout << q.Delete() << endl;
        }
        else if(op == 2)   // 判断空
        {
            cout << (q.Empty() ? 1 : 0) << endl;
        }
        else if(op == 3)   // 判断满
        {
            cout << (q.Full() ? 1 : 0) << endl;
        }
    }

    return 0;
}

函数的分文件编写 
原则：头文件写 声明（告诉编译器 有什么），源文件写 实现（告诉编译器 怎么干），主程序文件写 调用逻辑（告诉编译器 用这些做什么）。
一、头文件（.h/.hpp）
头文件的核心作用是对外暴露接口，让其他文件知道 “有哪些类、函数、常量可以用”，但不暴露具体实现细节。

典型头文件模板（Person.h）：
// 必写：头文件保护宏 
#ifndef _PERSON_H_
#define _PERSON_H_
// 必写：依赖的系统头文件
#include <string>
// 可选：枚举/常量声明
const int MAX_AGE = 120;
enum Gender { MALE, FEMALE };
// 必写：类的完整定义（声明）
class Person {
private:
    std::string name;
    int age;
    Gender gender;
public:
    // 必写：成员函数/构造/析构声明
    Person(); // 无参构造声明
    Person(std::string name, int age, Gender gender); // 带参构造声明
    std::string getName() const; // 成员函数声明（const要加）
    void setAge(int newAge);
    ~Person(); // 析构声明
};
// 必写：全局函数声明
std::string getGenderStr(Gender g);
#endif // _PERSON_H_
头文件保护宏
头文件保护宏是一组预处理指令（#ifndef/#define/#endif），核心作用是防止同一个头文件被多次#include，导致 “重定义” 编译错误—— 它是 C++ 中解决头文件重复包含问题的 “标准方案”。

#pragma once
是 C/C++ 编译器提供的非标准但广泛支持的预处理指令，作用和头文件保护宏（#ifndef/#define/#endif）完全一致 —— 防止头文件被多次#include导致的重定义错误，且写法更简洁。
二、源文件（.cpp）
源文件的核心作用是实现头文件中声明的内容，是代码的具体逻辑载体，编译器会把源文件编译为二进制目标文件。

典型源文件模板（Person.cpp）：
// 必写：包含对应头文件
#include "Person.h"
// 可选：实现所需的其他头文件
#include <iostream>

// 必写：构造函数实现（加Person::）
Person::Person() {
    name = "未知";
    age = 0;
    gender = MALE;
}

Person::Person(std::string name, int age, Gender gender) {
    this->name = name;
    this->age = (age <= MAX_AGE) ? age : 0; // 用头文件的常量
    this->gender = gender;
}

// 必写：成员函数实现
std::string Person::getName() const { // const和声明一致
    return name;
}

void Person::setAge(int newAge) {
    if (newAge >= 0 && newAge <= MAX_AGE) {
        age = newAge;
    } else {
        std::cout << "年龄不合法！" << std::endl;
    }
}

// 必写：析构函数实现
Person::~Person() {
    std::cout << name << "已销毁" << std::endl;
}

// 必写：全局函数实现
std::string getGenderStr(Gender g) {
    return (g == MALE) ? "男" : "女";
}
三、主程序文件（main.cpp）
主程序文件的核心是包含main函数（程序唯一入口），负责调用头文件声明的类 / 函数，实现业务逻辑，不写通用的类 / 函数实现（通用逻辑放源文件）。

典型主程序文件模板（main.cpp）：
// 必写：包含所需头文件（自定义+系统）
#include <iostream>
#include "Person.h"
// 必写：using namespace（可选，也可写std::）
using namespace std;
// 必写：main函数（程序入口）
int main() {
    // 可选：业务逻辑——创建对象、调用函数
    Person p1; // 调用无参构造
    p1.setAge(30);
    cout << "默认对象：" << p1.getName() << "，年龄：" << p1.getAge() << endl;
    Person p2("李四", 25, FEMALE); // 调用带参构造
    cout << "自定义对象：" << p2.getName() << "，性别：" << getGenderStr(p2.gender) << endl;
    return 0; // 程序正常退出
}
